window.CBT_DATA=window.CBT_DATA||{};window.CBT_DATA["written/2021-2"]={"track":"written","round":"2021-2","questions":[{"id":"written-2021-2-1","no":1,"unit":"소프트웨어 설계","q":"시스템의 구성요소로 볼 수 없는 것은?","choices":["Process","Feedback","Maintenance","Control"],"ans":3,"rate":62,"wiki":[{"title":"시스템","url":"https://itwiki.kr/w/시스템"}],"exp":{"concept":"시스템은 입력(Input)을 받아 처리(Process)하고 출력(Output)을 내며, 이 과정을 제어(Control)하고 결과를 다시 앞 단계로 돌려보내는 피드백(Feedback)으로 이루어진다. 자판기로 치면 동전 투입이 입력, 음료 고르기가 처리, 음료 배출이 출력이고, 잔액 확인과 재투입 안내가 제어와 피드백이다.","choices":[{"verdict":"오답","why":"처리(Process)는 입력된 자료를 가공해 출력으로 바꾸는 시스템의 구성요소다."},{"verdict":"오답","why":"피드백(Feedback)은 출력 결과를 검토해 다시 입력이나 처리 단계로 되돌리는 구성요소다."},{"verdict":"정답","why":"유지보수(Maintenance)는 시스템을 운영한 뒤 고치고 개선하는 활동(생명주기 단계)이지 시스템을 이루는 5대 구성요소가 아니다."},{"verdict":"오답","why":"제어(Control)는 각 과정이 올바르게 진행되도록 감독하고 조정하는 구성요소다."}],"keywords":[{"term":"시스템 5대 구성요소","desc":"입력, 처리, 출력, 제어, 피드백"},{"term":"피드백(Feedback)","desc":"출력 결과를 평가해 다시 입력·처리로 되돌려 개선하는 기능"},{"term":"제어(Control)","desc":"시스템의 각 과정이 정상 수행되도록 감독하는 기능"}],"memo":"입처출제피(입력·처리·출력·제어·피드백) 다섯 개만 구성요소다. 유지보수는 '활동'이라 빠진다."}},{"id":"written-2021-2-2","no":2,"unit":"소프트웨어 설계","q":"유스케이스(Usecase)에 대한 설명 중 옳은 것은?","choices":["유스케이스 다이어그램은 개발자의 요구를 추출하고 분석하기 위해 주로 사용한다.","액터는 대상 시스템과 상호 작용하는 사람이나 다른 시스템에 의한 역할이다.","사용자 액터는 본 시스템과 데이터를 주고받는 연동 시스템을 의미한다.","연동의 개념은 일방적으로 데이터를 파일이나 정해진 형식으로 넘겨주는 것을 의미한다."],"ans":2,"rate":56,"exp":{"concept":"유스케이스는 사용자 관점에서 시스템이 제공하는 기능을 나타낸 것이다. 유스케이스 다이어그램은 사용자의 요구를 추출하고 분석하는 데 쓰며, 시스템 밖에서 시스템과 상호작용하는 사람이나 다른 시스템을 액터(Actor)라고 한다. 액터는 사람인 사용자 액터와 다른 시스템인 시스템 액터로 나뉜다.","choices":[{"verdict":"오답","why":"유스케이스 다이어그램은 개발자가 아니라 사용자의 요구를 추출하고 분석하기 위해 사용한다."},{"verdict":"정답","why":"액터는 대상 시스템과 상호작용하는 사람이나 다른 시스템이 맡는 역할이라는 설명이 정의 그대로다."},{"verdict":"오답","why":"본 시스템과 데이터를 주고받는 연동 시스템은 시스템 액터다. 사용자 액터는 시스템을 직접 사용하는 사람을 말한다."},{"verdict":"오답","why":"연동은 데이터를 일방적으로 넘겨주는 것만이 아니라 양방향으로 데이터를 주고받는 것까지 포함하는 개념이다."}],"keywords":[{"term":"액터(Actor)","desc":"시스템 외부에서 시스템과 상호작용하는 사람 또는 다른 시스템의 역할"},{"term":"사용자 액터","desc":"시스템을 직접 사용하는 사람"},{"term":"시스템 액터","desc":"본 시스템과 데이터를 주고받는 다른(연동) 시스템"},{"term":"유스케이스(Use Case)","desc":"사용자 관점에서 본 시스템의 기능 단위"}],"memo":"사람이면 사용자 액터, 시스템이면 시스템 액터. 유스케이스는 '사용자' 요구 분석 도구라는 점이 단골 함정이다."}},{"id":"written-2021-2-3","no":3,"unit":"소프트웨어 설계","q":"요구사항 개발 프로세스의 순서로 옳은 것은?\n<img src=\"data/img/eip_written_20210515_003.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["㉠ - ㉡ - ㉢ - ㉣","㉠ - ㉢ - ㉡ - ㉣","㉠ - ㉣ - ㉡ - ㉢","㉠ - ㉡ - ㉣ - ㉢"],"ans":1,"rate":76,"wiki":[{"title":"요구 공학","url":"https://itwiki.kr/w/요구 공학"}],"exp":{"concept":"요구사항 개발은 요구를 끌어내고(도출), 정리·분석하고(분석), 문서로 적고(명세), 맞는지 확인하는(확인) 순서로 진행된다. 집을 지을 때 고객 이야기를 듣고, 정리하고, 설계 요청서로 쓰고, 고객에게 다시 확인받는 흐름과 같다.","choices":[{"verdict":"정답","why":"도출(Elicitation) → 분석(Analysis) → 명세(Specification) → 확인(Validation)이 요구사항 개발 프로세스의 표준 순서다."},{"verdict":"오답","why":"명세를 분석보다 먼저 할 수 없다. 분석으로 정리된 내용을 문서화하는 것이 명세다."},{"verdict":"오답","why":"확인은 작성된 명세서를 검토하는 마지막 단계이므로 분석·명세보다 앞설 수 없다."},{"verdict":"오답","why":"확인을 명세 전에 두면 검증할 문서가 없으므로 순서가 맞지 않다."}],"keywords":[{"term":"도출(Elicitation)","desc":"인터뷰, 설문, 브레인스토밍 등으로 요구사항을 수집하는 단계"},{"term":"분석(Analysis)","desc":"수집한 요구사항의 모순·누락을 찾고 정리하는 단계"},{"term":"명세(Specification)","desc":"분석한 요구사항을 문서(요구사항 명세서)로 작성하는 단계"},{"term":"확인(Validation)","desc":"명세된 요구사항이 사용자 의도와 맞는지 검토하는 단계"}],"memo":"도-분-명-확 순서. '모으고, 정리하고, 쓰고, 검사한다'로 외운다."}},{"id":"written-2021-2-4","no":4,"unit":"소프트웨어 설계","q":"객체지향 기법에서 같은 클래스에 속한 각각의 객체를 의미하는 것은?","choices":["instance","message","method","module"],"ans":1,"rate":70,"wiki":[{"title":"객체지향 기법","url":"https://itwiki.kr/w/객체지향 기법"}],"exp":{"concept":"클래스는 붕어빵 틀, 객체는 그 틀로 찍어낸 붕어빵이다. 같은 클래스로 만들어진 각각의 구체적인 객체를 인스턴스(Instance)라고 한다.","choices":[{"verdict":"정답","why":"인스턴스(Instance)는 클래스에 속한 각각의 구체적인 객체를 뜻한다."},{"verdict":"오답","why":"메시지(Message)는 객체에게 어떤 행위를 하도록 요청하는 명령이다."},{"verdict":"오답","why":"메소드(Method)는 객체가 수행하는 동작, 즉 클래스 안에 정의된 연산(함수)이다."},{"verdict":"오답","why":"모듈(Module)은 프로그램을 기능 단위로 나눈 독립적인 구성 단위다."}],"keywords":[{"term":"인스턴스(Instance)","desc":"클래스로부터 생성된 구체적인 객체 하나하나"},{"term":"클래스(Class)","desc":"공통 속성과 연산을 가진 객체들의 틀"},{"term":"메시지(Message)","desc":"객체에 행위를 요청하는 명령"}],"memo":"클래스=틀, 인스턴스=틀로 찍은 실물, 메시지=시키는 말, 메소드=하는 일."}},{"id":"written-2021-2-5","no":5,"unit":"소프트웨어 설계","q":"객체지향 설계에서 객체가 가지고 있는 속성과 오퍼레이션의 일부를 감추어서 객체의 외부에서는 접근이 불가능하게 하는 개념은? (문제 오류로 가답안 발표시 3번으로 발표되었지만 확정 답안 발표시 2, 3번이 정답처리 되었습니다. 여기서는 가답안인 3번을 누르면 정답 처리 됩니다.)","choices":["조직화(Organizing)","캡슐화(Encapsulation)","정보은닉(Infomation Hiding)","구조화(Structuralization)"],"ans":3,"rate":80,"wiki":[{"title":"객체지향 기법","url":"https://itwiki.kr/w/객체지향 기법"}],"exp":{"concept":"정보은닉(Information Hiding)은 객체 내부의 속성과 연산을 외부에서 보거나 접근하지 못하게 감추는 것이다. 캡슐화(Encapsulation)는 데이터와 그 데이터를 다루는 연산을 하나로 묶는 것이며, 묶으면서 내부를 감추는 효과가 함께 생긴다. 리모컨 내부 회로는 감추고 버튼만 보여 주는 것과 같다.","choices":[{"verdict":"오답","why":"조직화(Organizing)는 객체지향의 표준 핵심 개념으로 다루지 않는 용어다."},{"verdict":"오답","why":"캡슐화는 속성과 연산을 하나로 묶는 개념이다. 묶으면서 내부를 감추는 성질도 함께 가지므로 보기 내용상 맞는 답으로 볼 여지가 있다. 다만 감추는 개념 자체를 가리키는 말은 정보은닉이다."},{"verdict":"정답","why":"정보은닉은 객체의 속성과 연산 일부를 감추어 외부에서 접근할 수 없게 하는 개념으로, 문제 설명과 정확히 일치한다."},{"verdict":"오답","why":"구조화(Structuralization)는 객체지향 설계에서 이 뜻으로 쓰는 표준 용어가 아니다."}],"keywords":[{"term":"정보은닉(Information Hiding)","desc":"객체 내부 구현을 감추고 정해진 인터페이스로만 접근하게 하는 것"},{"term":"캡슐화(Encapsulation)","desc":"데이터와 그 데이터를 처리하는 함수를 하나로 묶는 것"},{"term":"추상화(Abstraction)","desc":"불필요한 세부를 빼고 핵심 특징만 뽑아내는 것"}],"memo":"'감춘다'가 핵심이면 정보은닉, '묶는다'가 핵심이면 캡슐화.","doubt":"캡슐화는 내부를 감추는 성질(정보은닉)을 포함하는 개념으로 설명되므로 보기 내용상 2번도 맞는 답으로 볼 수 있다. 문제에 붙은 안내에 따르면 확정 답안에서 2번과 3번이 모두 정답 처리되었고, 이 앱은 가답안인 3번으로 채점한다."}},{"id":"written-2021-2-6","no":6,"unit":"소프트웨어 설계","q":"GoF (Gangs of Four) 디자인 패턴에 대한 설명으로 틀린 것은?","choices":["factory method pattern은 상위클래스에서 객체를 생성하는 인터페이스를 정의하고, 하위클래스에서 인스턴스를 생성하도록 하는 방식이다.","prototype pattern은 prototype을 먼저 생성하고 인스턴스를 복제하여 사용하는 구조이다.","bridge pattern은 기존에 구현되어 있는 클래스에 기능 발생 시 기존 클래스를 재사용할 수 있도록 중간에서 맞춰주는 역할을 한다.","mediator pattern은 객체간의 통제와 지시의 역할을 하는 중재자를 두어 객체지향의 목표를 달성하게 해준다."],"ans":3,"rate":55,"exp":{"concept":"GoF 디자인 패턴은 생성·구조·행위 패턴으로 나뉜다. 브리지(Bridge) 패턴은 기능의 계층과 구현의 계층을 분리해 각각 독립적으로 확장할 수 있게 하는 구조 패턴이다. 기존 클래스를 재사용할 수 있도록 중간에서 인터페이스를 맞춰 주는 것은 어댑터(Adapter) 패턴이다. 콘센트 모양이 다른 해외에서 쓰는 '돼지코'가 어댑터다.","choices":[{"verdict":"오답","why":"팩토리 메소드(Factory Method) 패턴은 상위 클래스에서 객체 생성 인터페이스를 정의하고, 실제 어떤 객체를 만들지는 하위 클래스가 결정하게 하는 생성 패턴이므로 맞는 설명이다."},{"verdict":"오답","why":"프로토타입(Prototype) 패턴은 원본 객체를 먼저 만들고 이를 복제(clone)해 새 객체를 만드는 생성 패턴이므로 맞는 설명이다."},{"verdict":"정답","why":"기존 클래스를 재사용하도록 중간에서 맞춰 주는 것은 어댑터 패턴의 설명이다. 브리지 패턴은 기능과 구현을 분리해 독립적으로 확장하게 하는 패턴이다."},{"verdict":"오답","why":"중재자(Mediator) 패턴은 객체들 사이의 복잡한 상호작용을 중재자 객체가 통제·조정하게 하는 행위 패턴이므로 맞는 설명이다."}],"keywords":[{"term":"어댑터(Adapter) 패턴","desc":"호환되지 않는 인터페이스를 중간에서 변환해 재사용하게 하는 구조 패턴"},{"term":"브리지(Bridge) 패턴","desc":"기능 계층과 구현 계층을 분리해 각각 독립적으로 확장하게 하는 구조 패턴"},{"term":"중재자(Mediator) 패턴","desc":"객체 간 상호작용을 중재자 객체 하나가 통제하는 행위 패턴"},{"term":"프로토타입(Prototype) 패턴","desc":"원본 객체를 복제해 새 객체를 만드는 생성 패턴"}],"memo":"중간에서 맞춰 주는 '돼지코'는 어댑터, 기능과 구현을 '다리'로 분리하는 것은 브리지."}},{"id":"written-2021-2-7","no":7,"unit":"소프트웨어 설계","q":"요구사항 분석이 어려운 이유가 아닌 것은?","choices":["개발자와 사용자 간의 지식이나 표현의 차이가 커서 상호 이해가 쉽지 않다.","사용자의 요구는 예외가 거의 없어 열거와 구조화가 어렵지 않다.","사용자의 요구사항이 모호하고 불명확하다.","소프트웨어 개발 과정 중에 요구사항이 계속 변할 수 있다."],"ans":2,"rate":87,"exp":{"concept":"요구사항 분석이 어려운 이유는 개발자와 사용자의 지식·표현 차이, 모호하고 불명확한 요구, 개발 중에도 바뀌는 요구, 예외가 많아 열거·구조화가 어려운 점 등이다. '아닌 것'을 찾는 문제이므로 분석이 쉽다고 말하는 보기를 고르면 된다.","choices":[{"verdict":"오답","why":"개발자는 기술 용어로, 사용자는 업무 용어로 말하기 때문에 서로 이해하기 어렵다는 것은 실제 어려운 이유다."},{"verdict":"정답","why":"실제로 사용자의 요구에는 예외가 많아 빠짐없이 열거하고 구조화하기가 어렵다. 반대로 말하고 있으므로 어려운 이유가 아니다."},{"verdict":"오답","why":"'빠르게', '편하게'처럼 모호하고 불명확한 요구는 분석을 어렵게 하는 대표적 이유다."},{"verdict":"오답","why":"개발 도중에도 요구사항이 계속 바뀔 수 있다는 것은 실제 어려운 이유다."}],"keywords":[{"term":"요구사항 분석","desc":"수집한 요구를 정리해 모순과 누락을 찾고 구체화하는 활동"},{"term":"요구사항 변경","desc":"개발 중에도 계속 발생하므로 추적·관리가 필요함"},{"term":"요구사항 명세","desc":"분석 결과를 문서로 정리한 것"}],"memo":"'아닌 것은?'은 세 개가 같은 방향, 하나가 반대 방향이다. '어렵지 않다'고 말하는 보기를 먼저 찾는다."}},{"id":"written-2021-2-8","no":8,"unit":"소프트웨어 설계","q":"소프트웨어 아키텍처 설계에서 시스템 품질속성이 아닌 것은?","choices":["가용성 (Availability)","독립성 (Isolation)","변경 용이성 (Modifiability)","사용성(Usability)"],"ans":2,"rate":55,"exp":{"concept":"소프트웨어 아키텍처의 시스템 품질속성은 시스템이 얼마나 잘 동작하는지를 나타내는 기준으로, 가용성, 변경 용이성, 성능, 보안성, 사용성, 시험 용이성 등이 있다. 독립성(Isolation)은 트랜잭션 특성(ACID)의 하나이지 시스템 품질속성으로 꼽지 않는다.","choices":[{"verdict":"오답","why":"가용성(Availability)은 시스템이 필요할 때 장애 없이 사용 가능한 정도로, 시스템 품질속성이다."},{"verdict":"정답","why":"독립성(Isolation)은 동시에 실행되는 트랜잭션이 서로 간섭하지 않는다는 트랜잭션 특성(ACID의 I)으로, 아키텍처 시스템 품질속성이 아니다."},{"verdict":"오답","why":"변경 용이성(Modifiability)은 변경 요구를 적은 비용으로 반영할 수 있는 정도로, 시스템 품질속성이다."},{"verdict":"오답","why":"사용성(Usability)은 사용자가 쉽게 배우고 효율적으로 사용할 수 있는 정도로, 시스템 품질속성이다."}],"keywords":[{"term":"시스템 품질속성","desc":"가용성, 변경 용이성, 성능, 보안성, 사용성, 시험 용이성"},{"term":"가용성(Availability)","desc":"필요할 때 시스템을 쓸 수 있는 정도"},{"term":"ACID","desc":"트랜잭션 특성: 원자성, 일관성, 독립성(격리성), 지속성"}],"memo":"Isolation이 보이면 트랜잭션 ACID를 떠올린다. 아키텍처 품질속성 목록에는 없다."}},{"id":"written-2021-2-9","no":9,"unit":"소프트웨어 설계","q":"다음 설명에 해당하는 시스템으로 옳은 것은?\n<img src=\"data/img/eip_written_20210515_009.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["연계 서버","중계 서버","송신 시스템","수신 시스템"],"ans":3,"rate":67,"wiki":[{"title":"연계 시스템","url":"https://itwiki.kr/w/연계 시스템"}],"exp":{"concept":"시스템 인터페이스(연계 시스템)는 송신 시스템, 연계 서버(또는 중계 서버), 수신 시스템으로 구성된다. 송신 시스템은 보낼 데이터를 데이터베이스나 애플리케이션에서 꺼내 연계 테이블이나 파일 형태로 만들어 보내는 쪽이다. 택배로 치면 물건을 포장해 보내는 발송인이다.","choices":[{"verdict":"오답","why":"연계 서버는 송신 시스템과 수신 시스템 사이에서 데이터를 주고받고, 형식 변환이나 전송 상태 기록 등을 담당하는 서버다."},{"verdict":"오답","why":"중계 서버는 내부망과 외부망 사이에서 데이터를 중계하며 보안을 강화하는 서버다."},{"verdict":"정답","why":"연계할 데이터를 데이터베이스와 애플리케이션에서 연계 테이블 또는 파일 형태로 생성해 송신하는 시스템이 송신 시스템이다."},{"verdict":"오답","why":"수신 시스템은 받은 데이터를 자기 시스템에 맞는 형식으로 변환해 운영 데이터베이스에 반영하는 시스템이다."}],"keywords":[{"term":"송신 시스템","desc":"연계 데이터를 생성해 연계 테이블·파일로 보내는 시스템"},{"term":"수신 시스템","desc":"받은 데이터를 변환해 운영 DB에 반영하는 시스템"},{"term":"연계 서버","desc":"송수신 시스템 사이에서 데이터 송수신·형식 변환·상태 기록을 담당"},{"term":"중계 서버","desc":"내·외부망 사이에서 데이터를 중계하며 보안을 강화"}],"memo":"'생성하여 송신'이면 송신 시스템, '받아서 반영'이면 수신 시스템."}},{"id":"written-2021-2-10","no":10,"unit":"소프트웨어 설계","q":"CASE(Computer-Aided Software Engineering)의 원천 기술이 아닌 것은?","choices":["구조적 기법","프로토타이핑 기술","정보 저장소 기술","일괄처리 기술"],"ans":4,"rate":54,"wiki":[{"title":"CASE","url":"https://itwiki.kr/w/CASE"}],"exp":{"concept":"CASE는 소프트웨어 개발 과정을 컴퓨터 도구로 자동화해 돕는 기술이다. CASE의 원천 기술로는 구조적 기법, 프로토타이핑 기술, 자동 프로그래밍 기술, 정보 저장소 기술, 분산 처리 기술이 꼽힌다. 일괄처리(Batch) 기술은 여기에 들지 않는다.","choices":[{"verdict":"오답","why":"구조적 기법은 CASE의 원천 기술이다."},{"verdict":"오답","why":"프로토타이핑 기술은 CASE의 원천 기술이다."},{"verdict":"오답","why":"정보 저장소(Repository) 기술은 개발 정보를 저장·공유하는 CASE의 원천 기술이다."},{"verdict":"정답","why":"일괄처리 기술은 자료를 모아서 한꺼번에 처리하는 처리 방식일 뿐, CASE의 원천 기술이 아니다."}],"keywords":[{"term":"CASE","desc":"소프트웨어 개발 전 과정을 자동화 도구로 지원하는 기술"},{"term":"CASE 원천 기술","desc":"구조적 기법, 프로토타이핑, 자동 프로그래밍, 정보 저장소, 분산 처리"},{"term":"정보 저장소(Repository)","desc":"개발 산출물과 정보를 저장·공유하는 곳"}],"memo":"CASE 원천 기술은 '분산 처리'이지 '일괄 처리'가 아니다. 처리 방식 이름이 바뀐 함정을 조심한다."}},{"id":"written-2021-2-11","no":11,"unit":"소프트웨어 설계","q":"객체에게 어떤 행위를 하도록 지시하는 명령은?","choices":["Class","Package","Object","Message"],"ans":4,"rate":78,"wiki":[{"title":"객체지향 기법","url":"https://itwiki.kr/w/객체지향 기법"}],"exp":{"concept":"객체지향에서 객체들은 메시지(Message)를 주고받으며 일한다. 메시지는 한 객체가 다른 객체에게 특정 메소드를 실행하라고 요청하는 명령이다. 사람에게 '문 닫아 줘'라고 말하는 것이 메시지, 그 사람이 문을 닫는 동작이 메소드다.","choices":[{"verdict":"오답","why":"클래스(Class)는 공통된 속성과 연산을 가진 객체들의 틀이다."},{"verdict":"오답","why":"패키지(Package)는 관련된 클래스나 요소들을 묶은 그룹이다."},{"verdict":"오답","why":"객체(Object)는 데이터와 연산을 함께 가진 실체로, 명령 자체가 아니다."},{"verdict":"정답","why":"메시지(Message)는 객체에게 어떤 행위를 하도록 지시하는 명령이다."}],"keywords":[{"term":"메시지(Message)","desc":"객체에게 행위를 요청하는 명령"},{"term":"메소드(Method)","desc":"메시지를 받은 객체가 실제로 수행하는 연산"},{"term":"객체(Object)","desc":"속성(데이터)과 메소드를 함께 가진 실체"}],"memo":"지시하는 '말'은 메시지, 받은 쪽이 하는 '일'은 메소드."}},{"id":"written-2021-2-12","no":12,"unit":"소프트웨어 설계","q":"서브시스템이 입력 데이터를 받아 처리하고 결과를 다른 시스템에 보내는 작업이 반복되는 아키텍처 스타일은?","choices":["클라이언트 서버 구조","계층 구조","MVC 구조","파이프 필터 구조"],"ans":4,"rate":67,"exp":{"concept":"파이프 필터(Pipe-Filter) 구조는 각 서브시스템(필터)이 데이터를 받아 처리한 뒤 결과를 파이프로 다음 필터에 넘기는 과정이 반복되는 아키텍처다. 공장 컨베이어 벨트처럼 단계별로 가공해 넘긴다. 유닉스의 'ls | grep' 같은 파이프 명령이 대표적이다.","choices":[{"verdict":"오답","why":"클라이언트 서버 구조는 서비스를 요청하는 클라이언트와 제공하는 서버로 나뉜 구조다."},{"verdict":"오답","why":"계층 구조는 시스템을 여러 계층으로 나누고 각 계층이 바로 위·아래 계층과만 상호작용하는 구조다."},{"verdict":"오답","why":"MVC 구조는 모델(Model), 뷰(View), 컨트롤러(Controller)로 나누어 데이터와 화면, 제어를 분리하는 구조다."},{"verdict":"정답","why":"입력을 받아 처리하고 결과를 다음 시스템에 넘기는 작업이 반복되는 것은 파이프 필터 구조다."}],"keywords":[{"term":"파이프 필터 구조","desc":"필터(처리)와 파이프(전달)로 데이터를 단계별로 처리하는 구조"},{"term":"MVC 구조","desc":"모델·뷰·컨트롤러로 역할을 분리하는 구조"},{"term":"계층 구조","desc":"기능을 계층으로 나누고 인접 계층끼리만 통신하는 구조"}],"memo":"'받아서 처리하고 다음으로 넘긴다'가 반복되면 파이프 필터."}},{"id":"written-2021-2-13","no":13,"unit":"소프트웨어 설계","q":"럼바우(Rumbaugh)의 객체지향 분석에서 사용하는 분석 활동으로 옳은 것은?","choices":["객체 모델링, 동적 모델링, 정적 모델링","객체 모델링, 동적 모델링, 기능 모델링","동적 모델링, 기능 모델링, 정적 모델링","정적 모델링, 객체 모델링, 기능 모델링"],"ans":2,"exp":{"concept":"럼바우(Rumbaugh)의 객체지향 분석 기법(OMT)은 객체 모델링, 동적 모델링, 기능 모델링의 세 가지 활동으로 이루어진다. 객체 모델링은 객체와 관계를, 동적 모델링은 시간에 따른 상태 변화를, 기능 모델링은 자료 흐름을 표현한다.","choices":[{"verdict":"오답","why":"정적 모델링은 럼바우 분석 활동에 들지 않는다."},{"verdict":"정답","why":"객체 모델링, 동적 모델링, 기능 모델링이 럼바우 기법의 세 가지 분석 활동이다."},{"verdict":"오답","why":"정적 모델링이 들어 있고 객체 모델링이 빠졌으므로 틀리다."},{"verdict":"오답","why":"정적 모델링이 들어 있고 동적 모델링이 빠졌으므로 틀리다."}],"keywords":[{"term":"객체 모델링(Object Modeling)","desc":"객체와 그 관계를 객체 다이어그램으로 표현"},{"term":"동적 모델링(Dynamic Modeling)","desc":"시간에 따른 객체 상태 변화를 상태 다이어그램으로 표현"},{"term":"기능 모델링(Functional Modeling)","desc":"입력에서 출력까지 자료 흐름을 자료 흐름도(DFD)로 표현"}],"memo":"럼바우는 '객동기'(객체·동적·기능) 순서로 외운다. '정적'은 없다."}},{"id":"written-2021-2-14","no":14,"unit":"소프트웨어 설계","q":"UML 다이어그램이 아닌 것은?","choices":["액티비티 다이어그램(Activity diagram)","절차 다이어그램(Procedural diagram)","클래스 다이어그램(Class diagram)","시퀀스 다이어그램(Sequence diagram)"],"ans":2,"rate":57,"wiki":[{"title":"UML","url":"https://itwiki.kr/w/UML"}],"exp":{"concept":"UML 다이어그램은 구조(정적) 다이어그램과 행위(동적) 다이어그램으로 나뉜다. 구조 다이어그램에는 클래스, 객체, 컴포넌트, 배치, 복합 구조, 패키지 다이어그램이, 행위 다이어그램에는 유스케이스, 시퀀스, 커뮤니케이션, 상태, 활동, 타이밍 다이어그램 등이 있다. 절차 다이어그램이라는 UML 다이어그램은 없다.","choices":[{"verdict":"오답","why":"액티비티(활동) 다이어그램은 처리 흐름을 순서대로 표현하는 UML 행위 다이어그램이다."},{"verdict":"정답","why":"절차 다이어그램(Procedural diagram)은 UML에 정의된 다이어그램이 아니다."},{"verdict":"오답","why":"클래스 다이어그램은 클래스의 속성·연산과 클래스 간 관계를 표현하는 UML 구조 다이어그램이다."},{"verdict":"오답","why":"시퀀스 다이어그램은 객체 사이의 메시지 교환을 시간 순서로 표현하는 UML 행위 다이어그램이다."}],"keywords":[{"term":"구조 다이어그램","desc":"클래스, 객체, 컴포넌트, 배치, 복합 구조, 패키지"},{"term":"행위 다이어그램","desc":"유스케이스, 시퀀스, 커뮤니케이션, 상태, 활동, 타이밍"},{"term":"시퀀스 다이어그램","desc":"객체 간 메시지 흐름을 시간 순서로 표현"}],"memo":"UML 다이어그램 이름에 '절차'는 없다. 처리 흐름은 '활동(Activity)' 다이어그램이 맡는다."}},{"id":"written-2021-2-15","no":15,"unit":"소프트웨어 설계","q":"UML 모델에서 한 객체가 다른 객체에게 오퍼레이션을 수행하도록 지정하는 의미적 관계로 옳은 것은?","choices":["Dependency","Realization","Generalization","Association"],"ans":2,"rate":49,"wiki":[{"title":"UML","url":"https://itwiki.kr/w/UML"}],"exp":{"concept":"UML의 관계에는 연관, 집합, 포함, 일반화, 의존, 실체화가 있다. 실체화(Realization)는 한 사물이 다른 사물에게 수행해야 할 오퍼레이션을 지정하는 의미적 관계로, 인터페이스와 그 인터페이스를 구현하는 클래스 사이의 관계가 대표적이다.","choices":[{"verdict":"오답","why":"의존(Dependency)은 한 사물의 명세가 바뀌면 이를 사용하는 다른 사물에 영향을 주는 관계로, 짧은 시간 동안만 사용하는 관계에 쓴다."},{"verdict":"정답","why":"실체화(Realization)는 한 객체가 다른 객체에게 수행할 오퍼레이션을 지정하는 의미적 관계로, 문제 설명과 일치한다."},{"verdict":"오답","why":"일반화(Generalization)는 일반적인 개념과 구체적인 개념 사이의 상속(is-a) 관계다."},{"verdict":"오답","why":"연관(Association)은 두 개 이상의 사물이 서로 관련되어 있는 관계다."}],"keywords":[{"term":"실체화(Realization)","desc":"인터페이스가 지정한 오퍼레이션을 클래스가 구현하는 관계"},{"term":"일반화(Generalization)","desc":"상위(일반)와 하위(구체) 사이의 상속 관계"},{"term":"의존(Dependency)","desc":"한쪽 변경이 다른 쪽에 영향을 주는 일시적 사용 관계"},{"term":"연관(Association)","desc":"두 사물이 서로 관련되어 있는 관계"}],"memo":"'오퍼레이션을 수행하도록 지정'은 인터페이스 구현, 즉 실체화다."}},{"id":"written-2021-2-16","no":16,"unit":"소프트웨어 설계","q":"다음 중 상위 CASE 도구가 지원하는 주요기능으로 볼 수 없는 것은?","choices":["모델들 사이의 모순검사 기능","전체 소스코드 생성 기능","모델의 오류검증 기능","자료흐름도 작성 기능"],"ans":2,"rate":68,"wiki":[{"title":"CASE","url":"https://itwiki.kr/w/CASE"}],"exp":{"concept":"CASE 도구는 지원하는 개발 단계에 따라 상위 CASE와 하위 CASE로 나뉜다. 상위 CASE는 요구 분석과 설계 단계를 지원해 모델 작성, 모델 간 모순 검사, 오류 검증, 자료흐름도 작성 등을 돕는다. 하위 CASE는 구현 단계를 지원하며 소스 코드 생성이 대표 기능이다.","choices":[{"verdict":"오답","why":"모델들 사이의 모순 검사는 분석·설계 단계를 지원하는 상위 CASE의 기능이다."},{"verdict":"정답","why":"전체 소스 코드 생성은 구현 단계를 지원하는 하위 CASE의 기능이다."},{"verdict":"오답","why":"모델의 오류 검증은 상위 CASE의 기능이다."},{"verdict":"오답","why":"자료흐름도 작성은 분석 단계를 지원하는 상위 CASE의 기능이다."}],"keywords":[{"term":"상위 CASE","desc":"요구 분석·설계 단계 지원(모델 작성, 모순·오류 검사, DFD 작성)"},{"term":"하위 CASE","desc":"구현 단계 지원(소스 코드 생성 등)"},{"term":"통합 CASE","desc":"개발 전 과정을 지원하는 CASE"}],"memo":"위(상위)는 그림과 검사, 아래(하위)는 코드."}},{"id":"written-2021-2-17","no":17,"unit":"소프트웨어 설계","q":"요구사항 관리 도구의 필요성으로 틀린 것은?","choices":["요구사항 변경으로 인한 비용 편익 분석","기존 시스템과 신규 시스템의 성능 비교","요구사항 변경의 추적","요구사항 변경에 따른 영향 평가"],"ans":2,"rate":61,"exp":{"concept":"요구사항은 개발 중에 계속 바뀌므로 도구로 관리한다. 요구사항 관리 도구는 변경을 추적하고, 변경이 다른 부분에 미치는 영향을 평가하며, 변경에 따른 비용 편익을 분석하는 데 필요하다. 시스템 성능 비교는 요구사항 관리와 관계가 없다.","choices":[{"verdict":"오답","why":"요구사항 변경으로 생기는 비용과 편익을 분석하는 것은 요구사항 관리 도구가 필요한 이유다."},{"verdict":"정답","why":"기존 시스템과 신규 시스템의 성능 비교는 성능 테스트나 벤치마크로 하는 일이며, 요구사항 관리 도구의 필요성이 아니다."},{"verdict":"오답","why":"어떤 요구사항이 언제 어떻게 바뀌었는지 추적하는 것은 요구사항 관리 도구가 필요한 이유다."},{"verdict":"오답","why":"요구사항 변경이 설계·코드 등에 미치는 영향을 평가하는 것은 요구사항 관리 도구가 필요한 이유다."}],"keywords":[{"term":"요구사항 관리 도구","desc":"요구사항 변경의 추적, 영향 평가, 비용 편익 분석을 지원"},{"term":"추적성(Traceability)","desc":"요구사항과 설계·코드·테스트 사이의 연결을 따라갈 수 있는 성질"},{"term":"영향 분석","desc":"변경이 다른 산출물에 미치는 범위를 평가하는 활동"}],"memo":"요구사항 관리 도구는 '변경'에 관한 일(추적·영향·비용)만 한다. '성능'은 엉뚱한 보기다."}},{"id":"written-2021-2-18","no":18,"unit":"소프트웨어 설계","q":"애자일 개발 방법론이 아닌 것은?","choices":["스크럼(Scrum)","익스트림 프로그래밍(XP, eXtreme Programming)","기능 주도 개발(FDD, Feature Driven Development)","하둡(Hadoop)"],"ans":4,"rate":81,"wiki":[{"title":"애자일 방법론","url":"https://itwiki.kr/w/애자일 방법론"},{"title":"스크럼","url":"https://itwiki.kr/w/스크럼"},{"title":"하둡","url":"https://itwiki.kr/w/하둡"}],"exp":{"concept":"애자일(Agile) 개발 방법론은 계획보다 변화 대응과 고객 협력을 중시하며 짧은 주기로 반복 개발한다. 대표적으로 스크럼, 익스트림 프로그래밍(XP), 기능 주도 개발(FDD), 칸반, 린(Lean) 등이 있다. 하둡은 개발 방법론이 아니라 빅데이터 처리 기술이다.","choices":[{"verdict":"오답","why":"스크럼(Scrum)은 스프린트 단위로 반복 개발하는 대표적인 애자일 방법론이다."},{"verdict":"오답","why":"익스트림 프로그래밍(XP)은 짝 프로그래밍, 테스트 주도 개발 등을 실천하는 애자일 방법론이다."},{"verdict":"오답","why":"기능 주도 개발(FDD)은 기능 단위로 설계·구현을 짧게 반복하는 애자일 방법론이다."},{"verdict":"정답","why":"하둡(Hadoop)은 대용량 데이터를 여러 컴퓨터에 나누어 저장·처리하는 오픈 소스 분산 처리 프레임워크로, 개발 방법론이 아니다."}],"keywords":[{"term":"애자일(Agile)","desc":"변화에 빠르게 대응하며 짧은 주기로 반복 개발하는 방법론"},{"term":"스크럼(Scrum)","desc":"스프린트, 제품 백로그, 데일리 스크럼을 쓰는 애자일 방법론"},{"term":"XP(eXtreme Programming)","desc":"짝 프로그래밍, 테스트 우선 개발 등을 강조하는 애자일 방법론"},{"term":"하둡(Hadoop)","desc":"오픈 소스 기반 대용량 데이터 분산 저장·처리 프레임워크"}],"memo":"빅데이터 용어(하둡)가 방법론 목록에 끼어 있으면 그것이 답이다."}},{"id":"written-2021-2-19","no":19,"unit":"소프트웨어 설계","q":"GoF(Gangs of Four) 디자인 패턴 중 생성패턴으로 옳은 것은?","choices":["singleton pattern","adapter pattern","decorator pattern","state pattern"],"ans":1,"rate":66,"exp":{"concept":"GoF 디자인 패턴은 목적에 따라 생성, 구조, 행위 패턴으로 나뉜다. 생성 패턴은 객체를 만드는 방법을 다루며 추상 팩토리, 빌더, 팩토리 메소드, 프로토타입, 싱글톤의 5개가 있다.","choices":[{"verdict":"정답","why":"싱글톤(Singleton) 패턴은 클래스의 인스턴스를 하나만 만들도록 보장하는 생성 패턴이다."},{"verdict":"오답","why":"어댑터(Adapter) 패턴은 호환되지 않는 인터페이스를 맞춰 주는 구조 패턴이다."},{"verdict":"오답","why":"데코레이터(Decorator) 패턴은 객체에 기능을 동적으로 덧붙이는 구조 패턴이다."},{"verdict":"오답","why":"상태(State) 패턴은 객체의 상태에 따라 행동을 바꾸는 행위 패턴이다."}],"keywords":[{"term":"생성 패턴","desc":"추상 팩토리, 빌더, 팩토리 메소드, 프로토타입, 싱글톤"},{"term":"구조 패턴","desc":"어댑터, 브리지, 컴포지트, 데코레이터, 퍼사드, 플라이웨이트, 프록시"},{"term":"행위 패턴","desc":"옵서버, 상태, 전략, 중재자, 템플릿 메소드, 반복자, 커맨드 등"}],"memo":"생성 패턴 5개만 외우면 나머지는 구조나 행위로 거른다: 추상 팩토리·빌더·팩토리 메소드·프로토타입·싱글톤."}},{"id":"written-2021-2-20","no":20,"unit":"소프트웨어 설계","q":"사용자 인터페이스(UI)의 특징으로 틀린 것은?","choices":["구현하고자 하는 결과의 오류를 최소화한다.","사용자의 편의성을 높임으로써 작업시간을 증가시킨다.","막연한 작업 기능에 대해 구체적인 방법을 제시하여 준다.","사용자 중심의 상호 작용이 되도록 한다."],"ans":2,"rate":85,"wiki":[{"title":"사용자 인터페이스","url":"https://itwiki.kr/w/사용자 인터페이스"}],"exp":{"concept":"사용자 인터페이스(UI)는 사람과 시스템이 만나는 접점이다. 좋은 UI는 사용자 중심으로 상호작용하게 하고, 오류를 줄이며, 막연한 작업에 구체적인 방법을 제시해 작업 시간을 줄여 준다.","choices":[{"verdict":"오답","why":"UI는 사용자가 원하는 결과를 정확히 얻도록 도와 오류를 최소화한다."},{"verdict":"정답","why":"사용자의 편의성을 높이면 작업 시간은 줄어든다. 작업 시간을 증가시킨다는 설명은 틀리다."},{"verdict":"오답","why":"UI는 막연한 작업 기능에 대해 메뉴, 버튼 등으로 구체적인 방법을 제시해 준다."},{"verdict":"오답","why":"UI는 사용자 중심의 상호작용이 되도록 설계한다."}],"keywords":[{"term":"사용자 인터페이스(UI)","desc":"사용자와 시스템 사이의 상호작용 접점"},{"term":"UI 설계 원칙","desc":"직관성, 유효성, 학습성, 유연성"},{"term":"사용성(Usability)","desc":"사용자가 쉽고 효율적으로 쓸 수 있는 정도"}],"memo":"편의성이 높아지면 시간은 '감소'. 증가·감소를 바꿔 놓는 함정이다."}},{"id":"written-2021-2-21","no":21,"unit":"소프트웨어 개발","q":"힙 정렬(Heap Sort)에 대한 설명으로 틀린것은?","choices":["정렬할 입력 레코드들로 힙을 구성하고 가장 큰 키 값을 갖는 루트 노드를 제거하는 과정을 반복하여 정렬하는 기법이다.","평균 수행 시간은 O(nlog2n)이다.","완전 이진트리(complete binary tree)로 입력자료의 레코드를 구성한다.","최악의 수행 시간은 O(2n4)이다."],"ans":4,"rate":68,"wiki":[{"title":"힙 정렬","url":"https://itwiki.kr/w/힙 정렬"}],"exp":{"concept":"힙 정렬은 입력 자료로 완전 이진 트리 형태의 힙을 만든 뒤, 가장 큰 값을 가진 루트를 꺼내고 남은 자료로 힙을 다시 만드는 과정을 반복해 정렬한다. 힙을 재정비하는 데 트리 높이인 log n만큼 걸리고 이를 n번 하므로, 평균과 최악 모두 O(n log₂n)이다.","choices":[{"verdict":"오답","why":"힙을 구성하고 가장 큰 키를 가진 루트를 제거하는 과정을 반복한다는 것은 힙 정렬의 동작 그대로다."},{"verdict":"오답","why":"힙 정렬의 평균 수행 시간은 O(n log₂n)이므로 맞는 설명이다."},{"verdict":"오답","why":"힙은 완전 이진 트리로 구성하므로 맞는 설명이다."},{"verdict":"정답","why":"힙 정렬은 최악의 경우에도 O(n log₂n)이다. 이와 다른 값을 최악 수행 시간으로 제시했으므로 틀린 설명이다."}],"keywords":[{"term":"힙(Heap)","desc":"부모 키가 자식 키보다 크거나 같은(최대 힙) 완전 이진 트리"},{"term":"힙 정렬","desc":"평균·최악 모두 O(n log₂n)"},{"term":"퀵 정렬","desc":"평균 O(n log₂n), 최악 O(n²)"},{"term":"합병 정렬","desc":"평균·최악 모두 O(n log₂n)"}],"memo":"최악에도 n log n을 보장하는 것은 힙과 합병. 최악이 n²으로 떨어지는 것은 퀵."}},{"id":"written-2021-2-22","no":22,"unit":"소프트웨어 개발","q":"다음 중 단위 테스트를 통해 발견할 수 있는 오류가 아닌 것은?","choices":["알고리즘 오류에 따른 원치 않는 결과","탈출구가 없는 반복문의 사용","모듈 간의 비정상적 상호작용으로 인한 원치 않는 결과","틀린 계산 수식에 의한 잘못된 결과"],"ans":3,"rate":62,"wiki":[{"title":"단위 테스트","url":"https://itwiki.kr/w/단위 테스트"}],"exp":{"concept":"단위 테스트는 모듈 하나를 따로 떼어 내 그 안의 논리, 계산, 반복문 등이 제대로 동작하는지 확인한다. 모듈끼리 연결했을 때 생기는 문제는 통합 테스트에서 찾는다. 자동차 부품 하나하나를 검사하는 것이 단위 테스트, 조립 후 함께 돌려 보는 것이 통합 테스트다.","choices":[{"verdict":"오답","why":"알고리즘 오류로 인한 잘못된 결과는 모듈 내부 문제이므로 단위 테스트로 발견할 수 있다."},{"verdict":"오답","why":"탈출 조건이 없는 무한 반복문은 모듈 내부 논리 문제이므로 단위 테스트로 발견할 수 있다."},{"verdict":"정답","why":"모듈 간의 비정상적인 상호작용은 여러 모듈을 결합해야 드러나므로 통합 테스트에서 발견한다."},{"verdict":"오답","why":"틀린 계산 수식에 의한 잘못된 결과는 모듈 내부 문제이므로 단위 테스트로 발견할 수 있다."}],"keywords":[{"term":"단위 테스트(Unit Test)","desc":"개별 모듈의 기능과 내부 논리를 검사하는 테스트"},{"term":"통합 테스트(Integration Test)","desc":"모듈을 결합하며 인터페이스와 상호작용 오류를 찾는 테스트"},{"term":"테스트 드라이버·스텁","desc":"단위 테스트 시 상위·하위 모듈을 대신하는 임시 모듈"}],"memo":"'모듈 간', '인터페이스'라는 말이 나오면 단위가 아니라 통합 테스트다."}},{"id":"written-2021-2-23","no":23,"unit":"소프트웨어 개발","q":"다음 설명의 소프트웨어 테스트의 기본원칙은?\n<img src=\"data/img/eip_written_20210515_023.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["살충제 패러독스","결함 집중","오류 부재의 궤변","완벽한 테스팅은 불가능"],"ans":2,"rate":77,"exp":{"concept":"결함 집중(Defect Clustering)은 결함의 대부분이 소수의 특정 모듈에 몰려 있다는 테스트 원칙이다. 전체 결과의 80%가 20%의 원인에서 나온다는 파레토 법칙이 적용된다.","choices":[{"verdict":"오답","why":"살충제 패러독스는 같은 테스트 케이스를 반복하면 더 이상 새로운 결함을 찾지 못하므로 테스트 케이스를 계속 개선해야 한다는 원칙이다."},{"verdict":"정답","why":"파레토 법칙, 결함이 소수의 특정 모듈에 집중된다는 설명은 결함 집중 원칙이다."},{"verdict":"오답","why":"오류 부재의 궤변은 결함을 모두 없애도 사용자 요구를 만족하지 못하면 품질이 높다고 할 수 없다는 원칙이다."},{"verdict":"오답","why":"완벽한 테스팅은 불가능하다는 원칙은 모든 경우를 다 테스트할 수 없으므로 위험과 우선순위에 따라 테스트해야 한다는 뜻이다."}],"keywords":[{"term":"결함 집중","desc":"결함의 대부분이 소수 모듈에 집중됨(파레토 법칙)"},{"term":"살충제 패러독스","desc":"같은 테스트를 반복하면 새 결함을 찾지 못함"},{"term":"오류 부재의 궤변","desc":"결함이 없어도 요구를 못 맞추면 품질이 낮음"},{"term":"파레토 법칙","desc":"결과의 80%가 원인의 20%에서 비롯됨"}],"memo":"'파레토', '소수 모듈에 몰림'이면 결함 집중. 같은 약을 계속 쓰면 벌레가 내성이 생긴다는 것이 살충제 패러독스."}},{"id":"written-2021-2-24","no":24,"unit":"소프트웨어 개발","q":"버전 관리 항목 중 저장소에 새로운 버전의 파일로 갱신하는 것을 의미하는 용어는?","choices":["형상 감사(Configuration Audit)","롤백 (Rollback)","단위 테스트(Unit Test)","체크인(Check-In)"],"ans":4,"rate":69,"exp":{"concept":"버전 관리에서는 저장소의 파일을 꺼내 수정하고 다시 넣으며 버전을 관리한다. 저장소에서 파일을 가져오는 것을 체크아웃(Check-Out), 수정한 파일을 저장소에 새 버전으로 갱신하는 것을 체크인(Check-In)이라고 한다.","choices":[{"verdict":"오답","why":"형상 감사(Configuration Audit)는 변경 사항이 계획대로 올바르게 반영되었는지 검토·확인하는 형상 관리 활동이다."},{"verdict":"오답","why":"롤백(Rollback)은 변경을 취소하고 이전 상태로 되돌리는 것이다."},{"verdict":"오답","why":"단위 테스트(Unit Test)는 개별 모듈을 검사하는 테스트로, 버전 관리 용어가 아니다."},{"verdict":"정답","why":"체크인(Check-In)은 수정한 파일을 저장소에 새 버전으로 갱신하는 것이다."}],"keywords":[{"term":"체크인(Check-In)","desc":"수정한 파일을 저장소에 새 버전으로 반영"},{"term":"체크아웃(Check-Out)","desc":"저장소에서 파일을 내려받음"},{"term":"커밋(Commit)","desc":"변경 내용을 저장소에 확정해 기록"},{"term":"형상 감사","desc":"변경이 올바르게 이루어졌는지 검토하는 활동"}],"memo":"도서관처럼 생각한다: 빌려 가면 체크아웃, 반납(새 버전 넣기)하면 체크인."}},{"id":"written-2021-2-25","no":25,"unit":"소프트웨어 개발","q":"소프트웨어 테스트와 관련한 설명으로 틀린것은?","choices":["화이트 박스 테스트는 모듈의 논리적인 구조를 체계적으로 점검할 수 있다.","블랙박스 테스트는 프로그램의 구조를 고려하지 않는다.","테스트 케이스에는 일반적으로 시험 조건,테스트 데이터, 예상 결과가 포함되어야한다.","화이트박스 테스트에서 기본 경로(BasisPath)란 흐름 그래프의 시작 노드에서 종료노드까지의 서로 독립된 경로로 싸이클을 허용하지 않는 경로를 말한다."],"ans":4,"rate":63,"wiki":[{"title":"소프트웨어 테스트","url":"https://itwiki.kr/w/소프트웨어 테스트"}],"exp":{"concept":"화이트박스 테스트는 프로그램 내부 구조를 보고 테스트하고, 블랙박스 테스트는 내부 구조 없이 입력과 출력만 보고 테스트한다. 기초 경로(Basis Path) 테스트는 흐름 그래프에서 서로 독립적인 경로를 모두 실행해 보는 화이트박스 기법이며, 독립 경로는 반복문(사이클)도 거칠 수 있다.","choices":[{"verdict":"오답","why":"화이트박스 테스트는 모듈 안의 논리적 구조를 체계적으로 점검할 수 있다."},{"verdict":"오답","why":"블랙박스 테스트는 프로그램 구조를 보지 않고 요구 기능의 입출력만으로 검사한다."},{"verdict":"오답","why":"테스트 케이스는 일반적으로 테스트 조건, 테스트 데이터, 예상 결과를 포함한다."},{"verdict":"정답","why":"기본 경로는 시작 노드에서 종료 노드까지의 서로 독립된 경로이며 사이클(반복)을 허용한다. 사이클을 허용하지 않는다는 부분이 틀렸다."}],"keywords":[{"term":"기초 경로 테스트(Basis Path Test)","desc":"흐름 그래프의 독립 경로를 모두 실행하는 화이트박스 기법"},{"term":"순환 복잡도(Cyclomatic Complexity)","desc":"독립 경로의 수, V(G) = E - N + 2"},{"term":"테스트 케이스","desc":"테스트 조건, 테스트 데이터, 예상 결과로 구성"}],"memo":"기본 경로에서 반복문을 빼 버리면 반복 오류를 못 찾는다. '사이클 허용 안 함'은 틀린 말이다."}},{"id":"written-2021-2-26","no":26,"unit":"소프트웨어 개발","q":"애플리케이션의 처리량, 응답시간, 경과시간, 자원사용률에 대해 가상의 사용자를 생성하고 테스트를 수행함으로써 성능 목표를 달성하였는지를 확인하는 테스트 자동화 도구는?","choices":["명세 기반 테스트 설계 도구","코드 기반 테스트 설계 도구","기능 테스트 수행 도구","성능 테스트 도구"],"ans":4,"rate":76,"exp":{"concept":"테스트 자동화 도구에는 테스트 설계 도구, 테스트 수행 도구, 성능 테스트 도구, 테스트 통제 도구 등이 있다. 성능 테스트 도구는 가상의 사용자를 많이 만들어 동시에 접속시키고 처리량, 응답 시간, 경과 시간, 자원 사용률을 측정해 성능 목표를 달성했는지 확인한다.","choices":[{"verdict":"오답","why":"명세 기반 테스트 설계 도구는 요구사항 명세를 바탕으로 테스트 데이터를 만들어 내는 도구다."},{"verdict":"오답","why":"코드 기반 테스트 설계 도구는 소스 코드를 분석해 테스트 데이터를 만들어 내는 도구다."},{"verdict":"오답","why":"기능 테스트 수행 도구는 테스트를 자동으로 실행해 기능이 요구대로 동작하는지 확인하는 도구다."},{"verdict":"정답","why":"가상 사용자를 생성해 처리량, 응답 시간, 경과 시간, 자원 사용률을 측정하는 것은 성능 테스트 도구다."}],"keywords":[{"term":"성능 테스트 도구","desc":"가상 사용자로 부하를 주어 처리량·응답 시간·자원 사용률을 측정"},{"term":"테스트 수행 도구","desc":"테스트 데이터와 스크립트를 자동 실행하는 도구"},{"term":"테스트 통제 도구","desc":"테스트 계획·관리, 결함 추적 등을 지원하는 도구"}],"memo":"'가상의 사용자', '응답 시간'이 보이면 성능 테스트 도구."}},{"id":"written-2021-2-27","no":27,"unit":"소프트웨어 개발","q":"소프트웨어 형상 관리에 대한 설명으로 거리가 먼 것은?","choices":["소프트웨어에 가해지는 변경을 제어하고 관리한다.","프로젝트 계획, 분석서, 설계서, 프로그램, 테스트 케이스 모두 관리 대상이다.","대표적인 형상관리 도구로 Ant, Maven, Gradle 등이 있다.","유지 보수 단계뿐만 아니라 개발 단계에도 적용할 수 있다."],"ans":3,"rate":64,"exp":{"concept":"형상 관리(SCM)는 개발 중 만들어지는 모든 산출물(계획서, 분석서, 설계서, 코드, 테스트 케이스 등)의 변경을 식별하고 통제·기록하는 활동이다. 개발 단계와 유지보수 단계 모두에 적용한다. 대표 도구는 Git, SVN, CVS이며, Ant, Maven, Gradle은 빌드 도구다.","choices":[{"verdict":"오답","why":"소프트웨어에 가해지는 변경을 제어하고 관리하는 것이 형상 관리의 목적이다."},{"verdict":"오답","why":"프로젝트 계획, 분석서, 설계서, 프로그램, 테스트 케이스 모두 형상 관리 대상이다."},{"verdict":"정답","why":"Ant, Maven, Gradle은 소스 코드를 컴파일·패키징하는 빌드 자동화 도구다. 형상 관리 도구는 Git, SVN, CVS 등이다."},{"verdict":"오답","why":"형상 관리는 유지보수 단계뿐 아니라 개발 단계에도 적용한다."}],"keywords":[{"term":"형상 관리(SCM)","desc":"산출물의 변경을 식별·통제·기록·감사하는 활동"},{"term":"형상 관리 도구","desc":"Git, SVN(Subversion), CVS"},{"term":"빌드 자동화 도구","desc":"Ant, Maven, Gradle, Jenkins"}],"memo":"Git·SVN·CVS는 형상 관리, Ant·Maven·Gradle은 빌드. 둘을 섞어 놓는 함정이 자주 나온다."}},{"id":"written-2021-2-28","no":28,"unit":"소프트웨어 개발","q":"디지털 저작권 관리(DRM) 구성 요소가 아닌 것은?","choices":["Dataware house","DRM Controller","Packager","Contents Distributor"],"ans":1,"rate":55,"wiki":[{"title":"DRM","url":"https://itwiki.kr/w/DRM"}],"exp":{"concept":"디지털 저작권 관리(DRM)는 디지털 콘텐츠를 허가된 사용자만 정해진 범위로 쓰게 하는 기술이다. 구성 요소로 콘텐츠 제공자, 콘텐츠 분배자, 패키저, 보안 컨테이너, DRM 컨트롤러, 클리어링 하우스, 콘텐츠 소비자가 있다.","choices":[{"verdict":"정답","why":"데이터 웨어하우스(Data Warehouse)는 의사 결정을 위해 여러 시스템의 데이터를 모아 둔 통합 데이터 저장소로, DRM 구성 요소가 아니다. 이름이 비슷한 클리어링 하우스(Clearing House)와 헷갈리지 않아야 한다."},{"verdict":"오답","why":"DRM 컨트롤러(DRM Controller)는 배포된 콘텐츠의 이용 권한을 통제하는 DRM 구성 요소다."},{"verdict":"오답","why":"패키저(Packager)는 콘텐츠를 메타데이터와 함께 암호화해 배포 가능한 단위로 묶는 DRM 구성 요소다."},{"verdict":"오답","why":"콘텐츠 분배자(Contents Distributor)는 암호화된 콘텐츠를 유통하는 DRM 구성 요소다."}],"keywords":[{"term":"클리어링 하우스(Clearing House)","desc":"키 관리와 라이선스 발급, 사용량 기반 결제를 관리"},{"term":"패키저(Packager)","desc":"콘텐츠를 메타데이터와 함께 암호화해 묶음"},{"term":"DRM 컨트롤러","desc":"배포된 콘텐츠의 이용 권한을 통제"},{"term":"보안 컨테이너","desc":"콘텐츠를 안전하게 전달하기 위한 보안 장치"}],"memo":"DRM에는 '하우스'가 하나 있는데 그것은 웨어하우스가 아니라 클리어링 하우스다."}},{"id":"written-2021-2-29","no":29,"unit":"소프트웨어 개발","q":"다음 설명의 소프트웨어 버전 관리도구 방식은?\n<img src=\"data/img/eip_written_20210515_029.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["단일 저장소 방식","분산 저장소 방식","공유폴더 방식","클라이언트·서버 방식"],"ans":2,"rate":73,"exp":{"concept":"버전 관리 방식은 공유 폴더 방식, 클라이언트·서버 방식, 분산 저장소 방식으로 나뉜다. 분산 저장소 방식은 원격 저장소의 내용을 개발자 컴퓨터의 로컬 저장소에 통째로 복제해 두므로, 원격 저장소에 문제가 생겨도 로컬에서 작업할 수 있다. Git이 대표적이다.","choices":[{"verdict":"오답","why":"단일 저장소 방식은 버전 관리 도구의 표준 분류 이름이 아니다."},{"verdict":"정답","why":"원격 저장소와 로컬 저장소에 함께 저장되고, 로컬에서도 버전 관리가 가능하며, 대표 도구가 Git인 것은 분산 저장소 방식이다."},{"verdict":"오답","why":"공유 폴더 방식은 개발자들이 공유 폴더에 파일을 복사해 두는 방식으로, 대표 도구는 SCCS, RCS 등이다."},{"verdict":"오답","why":"클라이언트·서버 방식은 중앙 서버 저장소 하나에서 버전을 관리하는 방식으로, 대표 도구는 CVS, SVN이다. 서버에 문제가 생기면 작업이 어렵다."}],"keywords":[{"term":"분산 저장소 방식","desc":"원격·로컬 저장소에 모두 저장, 대표 도구 Git"},{"term":"클라이언트·서버 방식","desc":"중앙 저장소 하나로 관리, 대표 도구 CVS, SVN"},{"term":"공유 폴더 방식","desc":"공유 폴더에 파일 복사로 관리, 대표 도구 SCCS, RCS"}],"memo":"Git이 보이면 분산, SVN·CVS가 보이면 클라이언트·서버."}},{"id":"written-2021-2-30","no":30,"unit":"소프트웨어 개발","q":"블랙박스 테스트를 이용하여 발견할 수 있는 오류가 아닌 것은?","choices":["비정상적인 자료를 입력해도 오류 처리를 수행하지 않는 경우","정상적인 자료를 입력해도 요구된 기능이 제대로 수행되지 않는 경우","반복 조건을 만족하는데도 루프 내의 문장이 수행되지 않는 경우","경계값을 입력할 경우 요구된 출력 결과가 나오지 않는 경우"],"ans":3,"rate":68,"exp":{"concept":"블랙박스 테스트는 프로그램 내부를 보지 않고, 요구된 기능대로 입력에 맞는 출력이 나오는지만 확인한다. 그래서 잘못된 입력 처리, 기능 누락, 경계값 오류처럼 겉으로 드러나는 오류를 찾는다. 반복문 안의 문장이 실행되는지처럼 내부 구조에 관한 오류는 화이트박스 테스트로 찾는다.","choices":[{"verdict":"오답","why":"비정상적인 입력에 오류 처리를 하지 않는 것은 입출력만으로 드러나므로 블랙박스 테스트로 발견할 수 있다."},{"verdict":"오답","why":"정상 입력에도 요구 기능이 수행되지 않는 것은 기능 오류이므로 블랙박스 테스트로 발견할 수 있다."},{"verdict":"정답","why":"반복 조건을 만족하는데 루프 안의 문장이 수행되지 않는 것은 내부 논리 구조의 오류이므로 화이트박스 테스트(루프 검사 등)로 발견한다."},{"verdict":"오답","why":"경계값 입력에서 요구된 출력이 나오지 않는 것은 경계값 분석으로 찾는 블랙박스 테스트 대상이다."}],"keywords":[{"term":"블랙박스 테스트","desc":"내부 구조 없이 기능 명세의 입출력만 검사(동등 분할, 경계값 분석 등)"},{"term":"화이트박스 테스트","desc":"내부 논리 구조를 검사(기초 경로, 조건, 루프 검사 등)"},{"term":"경계값 분석","desc":"입력 범위의 경계 근처 값을 집중 테스트하는 블랙박스 기법"}],"memo":"'루프', '조건', '경로'처럼 코드 안이 보이는 말이 나오면 화이트박스다."}},{"id":"written-2021-2-31","no":31,"unit":"소프트웨어 개발","q":"다음 자료를 버블 정렬을 이용하여 오름차순으로 정렬할 경우 Pass 2의 결과는?\n<img src=\"data/img/eip_written_20210515_031.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["3, 5, 6, 7, 9","6, 7, 3, 5, 9","3, 5, 9, 6, 7","6, 3, 5, 7, 9"],"ans":4,"rate":62,"wiki":[{"title":"버블 정렬","url":"https://itwiki.kr/w/버블 정렬"}],"exp":{"concept":"버블 정렬은 이웃한 두 값을 비교해 앞이 더 크면 자리를 바꾸는 일을 끝까지 반복한다. 한 번 훑는 것(Pass)이 끝날 때마다 가장 큰 값이 맨 뒤로 가서 자리를 확정한다. 자료 9, 6, 7, 3, 5에서 Pass 1이 끝나면 9가 맨 뒤로 가 6, 7, 3, 5, 9가 되고, Pass 2에서는 6과 7은 그대로, 7과 3, 7과 5가 교환되어 7이 뒤에서 두 번째로 가 6, 3, 5, 7, 9가 된다.","choices":[{"verdict":"오답","why":"3, 5, 6, 7, 9는 Pass 3이 끝난 뒤의 결과(최종 정렬 결과)다."},{"verdict":"오답","why":"6, 7, 3, 5, 9는 Pass 1이 끝난 뒤의 결과다."},{"verdict":"오답","why":"3, 5, 9, 6, 7은 버블 정렬의 어떤 Pass에서도 나오지 않는 배열이다."},{"verdict":"정답","why":"Pass 1 결과 6, 7, 3, 5, 9에서 6과 7은 그대로, 7과 3 교환, 7과 5 교환이 일어나 Pass 2 결과는 6, 3, 5, 7, 9다."}],"keywords":[{"term":"버블 정렬(Bubble Sort)","desc":"인접한 두 원소를 비교·교환하며 큰 값을 뒤로 보내는 정렬, O(n²)"},{"term":"Pass(회전)","desc":"배열을 처음부터 한 번 훑는 과정, 끝날 때마다 가장 큰 값이 확정됨"},{"term":"선택 정렬","desc":"최솟값을 찾아 맨 앞과 교환하는 정렬로, 버블 정렬과 과정이 다름"}],"memo":"버블 정렬의 Pass k가 끝나면 큰 값 k개가 뒤에 확정된다. Pass 2 결과의 뒤 두 칸은 7, 9여야 한다."}},{"id":"written-2021-2-32","no":32,"unit":"소프트웨어 개발","q":"정렬된 N개의 데이터를 처리하는 데 O(N log₂N)의 시간이 소요되는 정렬 알고리즘은?","choices":["합병정렬","버블정렬","선택정렬","삽입정렬"],"ans":1,"rate":63,"wiki":[{"title":"정렬","url":"https://itwiki.kr/w/정렬"}],"exp":{"concept":"정렬 알고리즘의 시간 복잡도를 묻는 문제다. 합병 정렬은 자료를 반으로 계속 나눈 뒤(log₂N 단계) 각 단계에서 N개를 합치므로 자료가 이미 정렬되어 있든 아니든 항상 O(N log₂N)이 걸린다. 버블·선택·삽입 정렬은 O(N²) 계열이며, 삽입 정렬은 이미 정렬된 자료에서는 O(N)이다.","choices":[{"verdict":"정답","why":"합병 정렬은 입력 상태와 관계없이 항상 O(N log₂N)의 시간이 걸린다."},{"verdict":"오답","why":"버블 정렬은 평균과 최악이 O(N²)이다."},{"verdict":"오답","why":"선택 정렬은 자료 상태와 관계없이 항상 O(N²)이다."},{"verdict":"오답","why":"삽입 정렬은 평균과 최악이 O(N²)이며, 이미 정렬된 자료에서는 O(N)으로 가장 빠르다."}],"keywords":[{"term":"합병 정렬(Merge Sort)","desc":"분할 후 병합, 평균·최악 O(N log₂N)"},{"term":"삽입 정렬(Insertion Sort)","desc":"정렬된 자료에서 최선 O(N), 평균·최악 O(N²)"},{"term":"선택 정렬(Selection Sort)","desc":"항상 O(N²)"}],"memo":"N log N 계열은 퀵·합병·힙, N² 계열은 버블·선택·삽입."}},{"id":"written-2021-2-33","no":33,"unit":"소프트웨어 개발","q":"다음 postfix로 표현된 연산식의 연산 결과로 옳은 것은?\n<img src=\"data/img/eip_written_20210515_033.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["35","42","81","360"],"ans":2,"rate":88,"exp":{"concept":"후위 표기식(postfix)은 연산자를 피연산자 뒤에 쓰며, 스택으로 계산한다. 숫자를 만나면 스택에 넣고, 연산자를 만나면 스택에서 두 개를 꺼내 계산한 결과를 다시 넣는다. 3 4 * 5 6 * +를 계산하면 3과 4를 넣고 *에서 12, 5와 6을 넣고 *에서 30, 마지막 +에서 12 + 30 = 42가 된다. 중위식으로 바꾸면 (3 * 4) + (5 * 6)이다.","choices":[{"verdict":"오답","why":"35는 (3 + 4) * 5처럼 다른 순서로 계산해야 나오는 값으로, 이 식의 결과가 아니다."},{"verdict":"정답","why":"3 * 4 = 12, 5 * 6 = 30, 12 + 30 = 42이므로 정답이다."},{"verdict":"오답","why":"81은 이 식의 계산 결과가 아니다."},{"verdict":"오답","why":"360은 3 * 4 * 5 * 6처럼 모두 곱한 값으로, 이 식의 결과가 아니다."}],"keywords":[{"term":"후위 표기법(Postfix)","desc":"피연산자 뒤에 연산자를 쓰는 표기, 예: A B +"},{"term":"중위 표기법(Infix)","desc":"피연산자 사이에 연산자를 쓰는 일반 수식, 예: A + B"},{"term":"스택(Stack)","desc":"후입선출(LIFO) 구조, 후위식 계산에 사용"}],"memo":"후위식은 '숫자 둘 + 연산자'를 만나면 바로 묶는다: (3 4 *) (5 6 *) + → 12 + 30."}},{"id":"written-2021-2-34","no":34,"unit":"소프트웨어 개발","q":"EAI(Enterprise Application Integration) 구축 유형에서 애플리케이션 사이에 미들웨어를 두어 처리하는 것은? (문제 오류로 가답안 발표시 1번으로 발표되었지만 확정 답안 발표시 1, 3, 4번이 정답처리 되었습니다. 여기서는 가답안인 1번을 누르면 정답 처리 됩니다.)","choices":["Message Bus","Point-to-point","Hub &Spoke","Hybrid"],"ans":1,"rate":84,"exp":{"concept":"EAI(기업 애플리케이션 통합)는 기업 안의 여러 애플리케이션을 연결해 데이터와 업무를 통합하는 솔루션이다. 구축 유형은 포인트 투 포인트, 허브 앤 스포크, 메시지 버스, 하이브리드의 4가지다. 이 중 애플리케이션 사이에 미들웨어(버스)를 두어 처리하는 대표 유형이 메시지 버스다.","choices":[{"verdict":"정답","why":"메시지 버스(Message Bus)는 애플리케이션 사이에 미들웨어(버스)를 두어 처리하는 유형으로, 이 문항의 정답이다."},{"verdict":"오답","why":"포인트 투 포인트(Point-to-point)는 미들웨어 없이 애플리케이션끼리 1:1로 직접 연결하는 유형이다."},{"verdict":"오답","why":"허브 앤 스포크(Hub & Spoke)는 중앙의 허브 시스템을 거쳐 데이터를 전송하는 중앙 집중형 유형이다. 허브가 애플리케이션 사이에서 중개 역할을 하므로 보기 내용상 미들웨어를 두는 유형으로 볼 여지가 있다."},{"verdict":"오답","why":"하이브리드(Hybrid)는 그룹 내부는 허브 앤 스포크, 그룹 간에는 메시지 버스를 쓰는 혼합 유형이다. 두 방식 모두 중간 매개를 두므로 보기 내용상 미들웨어를 두는 유형으로 볼 여지가 있다."}],"keywords":[{"term":"포인트 투 포인트","desc":"미들웨어 없이 1:1 직접 연결, 변경·재사용 어려움"},{"term":"허브 앤 스포크","desc":"중앙 허브를 거쳐 전송, 허브 장애 시 전체 영향"},{"term":"메시지 버스","desc":"애플리케이션 사이에 미들웨어 버스를 두어 처리, 확장성 우수"},{"term":"하이브리드","desc":"그룹 내는 허브 앤 스포크, 그룹 간은 메시지 버스"}],"memo":"미들웨어가 '없는' 유형은 포인트 투 포인트 하나뿐이다.","doubt":"애플리케이션 사이에 중간 매개를 두지 않는 유형은 2번(포인트 투 포인트)뿐이어서, 보기 내용상 3번(허브 앤 스포크)과 4번(하이브리드)도 맞는 답으로 볼 수 있다. 문제에 붙은 안내에 따르면 확정 답안에서 1, 3, 4번이 모두 정답 처리되었고, 이 앱은 가답안인 1번으로 채점한다."}},{"id":"written-2021-2-35","no":35,"unit":"소프트웨어 개발","q":"인터페이스 구현 검증 도구가 아닌 것은?","choices":["Foxbase","STAF","watir","xUnit"],"ans":1,"rate":58,"exp":{"concept":"인터페이스 구현 검증 도구는 모듈 간 인터페이스가 제대로 동작하는지 테스트하는 도구다. xUnit, STAF, FitNesse, NTAF, Selenium, watir가 대표적이다.","choices":[{"verdict":"정답","why":"Foxbase는 예전에 쓰이던 데이터베이스 관리 프로그램으로, 인터페이스 구현 검증 도구가 아니다."},{"verdict":"오답","why":"STAF는 서비스 호출과 컴포넌트 재사용 등 다양한 환경을 지원하는 테스트 프레임워크로, 인터페이스 구현 검증 도구다."},{"verdict":"오답","why":"watir는 루비(Ruby) 기반의 웹 애플리케이션 테스트 프레임워크로, 인터페이스 구현 검증 도구다."},{"verdict":"오답","why":"xUnit은 JUnit, CppUnit 등 다양한 언어를 지원하는 단위 테스트 프레임워크로, 인터페이스 구현 검증 도구다."}],"keywords":[{"term":"xUnit","desc":"Java(JUnit), C++(CppUnit) 등 다양한 언어용 단위 테스트 프레임워크"},{"term":"STAF","desc":"서비스 호출·컴포넌트 재사용 등을 지원하는 테스트 프레임워크"},{"term":"FitNesse","desc":"웹 기반 테스트 케이스 설계·실행·결과 확인 프레임워크"},{"term":"watir","desc":"Ruby 기반 웹 애플리케이션 테스트 프레임워크"}],"memo":"검증 도구 6개(xUnit, STAF, FitNesse, NTAF, Selenium, watir)를 외워 두면 낯선 이름이 바로 걸러진다."}},{"id":"written-2021-2-36","no":36,"unit":"소프트웨어 개발","q":"클린코드 작성원칙에 대한 설명으로 틀린 것은?","choices":["코드의 중복을 최소화 한다.","코드가 다른 모듈에 미치는 영향을 최대화하도록 작성한다.","누구든지 코드를 쉽게 읽을 수 있도록 작성한다.","간단하게 코드를 작성한다."],"ans":2,"rate":89,"exp":{"concept":"클린 코드는 누구나 쉽게 읽고 고칠 수 있게 작성한 코드다. 작성 원칙은 가독성, 단순성, 의존성 배제, 중복성 최소화, 추상화다. 다른 모듈에 미치는 영향은 최소화해야 한다.","choices":[{"verdict":"오답","why":"중복 코드를 줄이는 것은 클린 코드의 중복성 최소화 원칙이다."},{"verdict":"정답","why":"코드가 다른 모듈에 미치는 영향은 최소화해야 한다(의존성 배제). 최대화한다는 설명은 틀리다."},{"verdict":"오답","why":"누구든지 쉽게 읽을 수 있게 작성하는 것은 가독성 원칙이다."},{"verdict":"오답","why":"간단하게 작성하는 것은 단순성 원칙이다."}],"keywords":[{"term":"클린 코드(Clean Code)","desc":"가독성이 높고 단순하며 의존성과 중복이 적은 코드"},{"term":"의존성 배제","desc":"다른 모듈에 미치는 영향을 최소화하는 원칙"},{"term":"중복성 최소화","desc":"같은 코드를 반복하지 않는 원칙(DRY)"}],"memo":"클린 코드 원칙은 '가단의중추'(가독성·단순성·의존성 배제·중복성 최소화·추상화)."}},{"id":"written-2021-2-37","no":37,"unit":"소프트웨어 개발","q":"소프트웨어 패키징에 대한 설명으로 틀린 것은?","choices":["패키징은 개발자 중심으로 진행한다.","신규 및 변경 개발소스를 식별하고, 이를 모듈화하여 상용제품으로 패키징 한다.","고객의 편의성을 위해 매뉴얼 및 버전관리를 지속적으로 한다.","범용 환경에서 사용이 가능하도록 일반적인 배포 형태로 패키징이 진행된다."],"ans":1,"rate":89,"exp":{"concept":"소프트웨어 패키징은 개발이 끝난 프로그램을 고객이 설치해 쓸 수 있도록 묶는 일이다. 사용자 중심으로 진행하며, 신규·변경 소스를 식별해 모듈화하고, 범용 환경에서 쓸 수 있는 일반적인 배포 형태로 만들며, 매뉴얼과 버전 관리를 지속적으로 한다.","choices":[{"verdict":"정답","why":"패키징은 개발자가 아니라 사용자(고객) 중심으로 진행한다."},{"verdict":"오답","why":"신규·변경 개발 소스를 식별하고 모듈화해 상용 제품으로 패키징하는 것은 맞는 설명이다."},{"verdict":"오답","why":"고객의 편의를 위해 매뉴얼과 버전 관리를 지속적으로 하는 것은 맞는 설명이다."},{"verdict":"오답","why":"범용 환경에서 사용 가능하도록 일반적인 배포 형태로 패키징하는 것은 맞는 설명이다."}],"keywords":[{"term":"소프트웨어 패키징","desc":"개발 완료된 모듈을 사용자가 설치·사용할 수 있게 배포 형태로 묶는 일"},{"term":"릴리즈 노트","desc":"배포 버전의 변경 사항, 기능, 결함 수정 내용을 정리한 문서"},{"term":"DRM","desc":"패키징된 콘텐츠의 저작권을 보호하는 기술"}],"memo":"패키징·매뉴얼·UI 문제에서 '개발자 중심'이 나오면 틀린 보기다. 항상 사용자 중심."}},{"id":"written-2021-2-38","no":38,"unit":"소프트웨어 개발","q":"공학적으로 잘된 소프트웨어(Well Engineered Software)의 설명 중 틀린 것은?","choices":["소프트웨어는 유지보수가 용이해야 한다.","소프트웨어는 신뢰성이 높아야 한다.","소프트웨어는 사용자 수준에 무관하게 일관된 인터페이스를 제공해야 한다.","소프트웨어는 충분한 테스팅을 거쳐야 한다."],"ans":3,"rate":94,"exp":{"concept":"공학적으로 잘된 소프트웨어는 유지보수가 쉽고, 신뢰성이 높고, 충분히 테스트되었으며, 사용자 수준에 맞는 적절한 인터페이스를 제공한다. 초보자와 숙련자의 요구가 다르므로 인터페이스는 사용자 수준을 고려해야 한다.","choices":[{"verdict":"오답","why":"유지보수가 용이해야 한다는 것은 잘된 소프트웨어의 조건이다."},{"verdict":"오답","why":"신뢰성이 높아야 한다는 것은 잘된 소프트웨어의 조건이다."},{"verdict":"정답","why":"잘된 소프트웨어는 사용자 수준과 무관한 일관된 인터페이스가 아니라, 사용자 수준에 맞는 적절한 인터페이스를 제공해야 한다."},{"verdict":"오답","why":"충분한 테스팅을 거쳐야 한다는 것은 잘된 소프트웨어의 조건이다."}],"keywords":[{"term":"Well Engineered Software","desc":"유지보수 용이, 높은 신뢰성, 충분한 테스트, 사용자 수준에 맞는 인터페이스"},{"term":"신뢰성(Reliability)","desc":"정해진 기능을 오류 없이 수행하는 정도"},{"term":"유지보수성(Maintainability)","desc":"변경·수정을 쉽게 할 수 있는 정도"}],"memo":"'사용자 수준에 무관하게'처럼 사용자를 고려하지 않는 표현은 틀린 보기다."}},{"id":"written-2021-2-39","no":39,"unit":"소프트웨어 개발","q":"테스트와 디버그의 목적으로 옳은 것은?","choices":["테스트는 오류를 찾는 작업이고 디버깅은 오류를 수정하는 작업이다.","테스트는 오류를 수정하는 작업이고 디버깅은 오류를 찾는 작업이다.","둘 다 소프트웨어의 오류를 찾는 작업으로 오류 수정은 하지 않는다.","둘 다 소프트웨어 오류의 발견, 수정과 무관하다."],"ans":1,"rate":74,"exp":{"concept":"테스트는 소프트웨어에 오류가 있는지 찾아내는 작업이고, 디버깅은 찾은 오류의 원인을 밝혀 고치는 작업이다. 건강검진으로 병을 찾는 것이 테스트, 의사가 치료하는 것이 디버깅이다.","choices":[{"verdict":"정답","why":"테스트는 오류를 찾고, 디버깅은 오류를 수정한다는 설명이 맞다."},{"verdict":"오답","why":"테스트와 디버깅의 역할을 서로 바꾸어 설명했으므로 틀리다."},{"verdict":"오답","why":"디버깅은 오류의 원인을 찾아 수정하는 작업이므로 둘 다 수정하지 않는다는 설명은 틀리다."},{"verdict":"오답","why":"테스트와 디버깅 모두 오류의 발견·수정과 직접 관련이 있으므로 틀리다."}],"keywords":[{"term":"테스트(Test)","desc":"소프트웨어의 오류(결함)를 발견하는 활동"},{"term":"디버깅(Debugging)","desc":"발견된 오류의 원인을 찾아 수정하는 활동"},{"term":"버그(Bug)","desc":"프로그램의 결함이나 오류"}],"memo":"디버깅의 de-는 '제거'. 버그를 없애는 일이 디버깅이다."}},{"id":"written-2021-2-40","no":40,"unit":"소프트웨어 개발","q":"다음 중 스택을 이용한 연산과 거리가 먼 것은?","choices":["선택정렬","재귀호출","후위표현(Post-fix expression)의 연산","깊이우선탐색"],"ans":1,"rate":51,"exp":{"concept":"스택(Stack)은 나중에 넣은 것을 먼저 꺼내는 후입선출(LIFO) 구조다. 함수 호출 기록을 쌓는 재귀 호출, 후위 표기식 계산, 깊이 우선 탐색(DFS)이 스택을 사용한다. 선택 정렬은 배열에서 최솟값을 골라 교환할 뿐 스택이 필요 없다.","choices":[{"verdict":"정답","why":"선택 정렬은 남은 원소 중 최솟값을 찾아 앞자리와 교환하는 정렬로, 스택을 이용하지 않는다."},{"verdict":"오답","why":"재귀 호출은 함수를 호출할 때마다 복귀 주소와 지역 변수를 스택에 쌓으므로 스택을 이용한다."},{"verdict":"오답","why":"후위 표현식 연산은 피연산자를 스택에 넣고 연산자를 만나면 꺼내 계산하므로 스택을 이용한다."},{"verdict":"오답","why":"깊이 우선 탐색(DFS)은 방문 경로를 스택에 쌓으며 깊이 들어가므로 스택을 이용한다."}],"keywords":[{"term":"스택(Stack)","desc":"후입선출(LIFO) 자료 구조"},{"term":"큐(Queue)","desc":"선입선출(FIFO) 자료 구조, 너비 우선 탐색(BFS)에 사용"},{"term":"깊이 우선 탐색(DFS)","desc":"스택을 이용해 한 경로를 끝까지 따라가는 탐색"}],"memo":"DFS는 스택, BFS는 큐. 재귀·후위식·DFS는 스택 3종 세트."}},{"id":"written-2021-2-41","no":41,"unit":"데이터베이스 구축","q":"병렬 데이터베이스 환경 중 수평 분할에서 활용되는 분할 기법이 아닌 것은?","choices":["라운드-로빈","범위 분할","예측 분할","해시 분할"],"ans":3,"rate":50,"exp":{"concept":"병렬 데이터베이스에서 수평 분할은 테이블의 행(튜플)을 여러 디스크나 서버에 나누어 저장하는 것이다. 나누는 방법에는 차례로 돌아가며 나누는 라운드 로빈, 값의 범위로 나누는 범위 분할, 해시 함수 값으로 나누는 해시 분할 등이 있다.","choices":[{"verdict":"오답","why":"라운드 로빈(Round-Robin)은 행을 각 분할에 차례로 돌아가며 배치하는 수평 분할 기법이다."},{"verdict":"오답","why":"범위 분할(Range Partitioning)은 키 값의 범위에 따라 행을 나누는 수평 분할 기법이다."},{"verdict":"정답","why":"예측 분할은 수평 분할 기법으로 쓰는 표준 용어가 아니다."},{"verdict":"오답","why":"해시 분할(Hash Partitioning)은 해시 함수 결과에 따라 행을 나누는 수평 분할 기법이다."}],"keywords":[{"term":"수평 분할","desc":"테이블을 행 단위로 나누어 저장"},{"term":"라운드 로빈 분할","desc":"행을 순서대로 돌아가며 각 분할에 배치"},{"term":"범위 분할","desc":"키 값의 범위로 분할"},{"term":"해시 분할","desc":"해시 함수 값으로 분할"}],"memo":"수평 분할 기법은 라운드 로빈·범위·해시(그리고 리스트). '예측'은 없다."}},{"id":"written-2021-2-42","no":42,"unit":"데이터베이스 구축","q":"시스템 카탈로그에 대한 설명으로 옳지 않은 것은?","choices":["사용자가 직접 시스템 카탈로그의 내용을 갱신하여 데이터베이스 무결성을 유지한다.","시스템 자신이 필요로 하는 스키마 및 여러가지 객체에 관한 정보를 포함하고 있는 시스템 데이터베이스이다.","시스템 카탈로그에 저장되는 내용을 메타데이터라고도 한다.","시스템 카탈로그는 DBMS가 스스로 생성하고 유지한다."],"ans":1,"rate":70,"wiki":[{"title":"시스템 카탈로그","url":"https://itwiki.kr/w/시스템 카탈로그"}],"exp":{"concept":"시스템 카탈로그는 데이터베이스에 있는 테이블, 뷰, 인덱스, 사용자, 권한 등 모든 객체에 대한 정보(메타데이터)를 담은 시스템 데이터베이스다. DBMS가 스스로 만들고 유지하며, 사용자는 SELECT로 조회만 할 수 있고 직접 수정할 수는 없다.","choices":[{"verdict":"정답","why":"시스템 카탈로그는 DBMS가 자동으로 갱신하며, 사용자가 직접 내용을 갱신할 수 없다. 사용자는 조회만 가능하다."},{"verdict":"오답","why":"시스템 카탈로그는 시스템이 필요로 하는 스키마와 여러 객체 정보를 담은 시스템 데이터베이스이므로 맞는 설명이다."},{"verdict":"오답","why":"카탈로그에 저장되는 '데이터에 관한 데이터'를 메타데이터라고 하므로 맞는 설명이다."},{"verdict":"오답","why":"시스템 카탈로그는 DBMS가 스스로 생성하고 유지하므로 맞는 설명이다."}],"keywords":[{"term":"시스템 카탈로그(System Catalog)","desc":"DB 객체 정보를 담은 시스템 DB, 데이터 사전(Data Dictionary)이라고도 함"},{"term":"메타데이터(Metadata)","desc":"데이터에 관한 데이터"},{"term":"데이터 디렉터리","desc":"데이터 사전의 정보에 접근하는 데 필요한 정보를 관리, 시스템만 접근 가능"}],"memo":"카탈로그는 DBMS가 관리하고 사용자는 '보기만' 한다(SELECT 가능, 갱신 불가)."}},{"id":"written-2021-2-43","no":43,"unit":"데이터베이스 구축","q":"SQL 문에서 SELECT에 대한 설명으로 옳지않은 것은?","choices":["FROM 절에는 질의에 의해 검색될 데이터들을 포함하는 테이블명을 기술한다.","검색결과에 중복되는 레코드를 없애기위해서는 WHERE 절에 'DISTINCT'키워드를 사용한다.","HAVING 절은 GROUP BY 절과 함께 사용되며, 그룹에 대한 조건을 지정한다.","ORDER BY 절은 특정 속성을 기준으로 정렬하여 검색할 때 사용한다."],"ans":2,"rate":67,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"SELECT 문은 SELECT(가져올 열) → FROM(테이블) → WHERE(행 조건) → GROUP BY(그룹) → HAVING(그룹 조건) → ORDER BY(정렬)로 구성된다. 중복 행을 없애는 DISTINCT는 WHERE 절이 아니라 SELECT 절에 쓴다.","choices":[{"verdict":"오답","why":"FROM 절에는 검색할 데이터가 들어 있는 테이블 이름을 쓴다."},{"verdict":"정답","why":"중복 레코드를 없애는 DISTINCT는 'SELECT DISTINCT 열이름'처럼 SELECT 절에 쓴다. WHERE 절에 쓴다는 설명은 틀리다."},{"verdict":"오답","why":"HAVING 절은 GROUP BY와 함께 쓰여 그룹에 대한 조건을 지정한다."},{"verdict":"오답","why":"ORDER BY 절은 특정 속성을 기준으로 정렬할 때 쓴다(기본 오름차순 ASC, 내림차순 DESC)."}],"keywords":[{"term":"DISTINCT","desc":"SELECT 절에서 중복 행을 제거"},{"term":"HAVING","desc":"GROUP BY로 묶은 그룹에 조건을 지정"},{"term":"ORDER BY","desc":"결과를 정렬, ASC 오름차순·DESC 내림차순"},{"term":"WHERE","desc":"개별 행에 대한 조건을 지정"}],"memo":"DISTINCT는 SELECT 바로 뒤. 'SELECT DISTINCT'를 한 단어처럼 외운다."}},{"id":"written-2021-2-44","no":44,"unit":"데이터베이스 구축","q":"SQL에서 VIEW를 삭제할 때 사용하는 명령은?","choices":["ERASE","KILL","DROP","DELETE"],"ans":3,"rate":81,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"뷰(VIEW)는 테이블처럼 정의된 객체이므로 DDL 명령으로 만들고 지운다. 뷰를 만들 때는 CREATE VIEW, 삭제할 때는 DROP VIEW를 쓴다. 뷰는 ALTER로 정의를 바꿀 수 없어서 바꾸려면 삭제 후 다시 만든다.","choices":[{"verdict":"오답","why":"ERASE는 SQL 명령어가 아니다."},{"verdict":"오답","why":"KILL은 SQL 표준의 객체 삭제 명령어가 아니다."},{"verdict":"정답","why":"DROP은 테이블, 뷰, 인덱스 등 객체를 삭제하는 DDL 명령으로, 'DROP VIEW 뷰이름'으로 뷰를 삭제한다."},{"verdict":"오답","why":"DELETE는 테이블의 행(데이터)을 삭제하는 DML 명령으로, 뷰 객체 자체를 삭제하지 않는다."}],"keywords":[{"term":"DROP","desc":"테이블·뷰·인덱스 등 객체를 삭제하는 DDL"},{"term":"DELETE","desc":"테이블의 행을 삭제하는 DML"},{"term":"뷰(VIEW)","desc":"기본 테이블에서 유도된 가상 테이블, ALTER로 변경 불가"}],"memo":"객체(틀)를 없애면 DROP, 내용(행)을 지우면 DELETE."}},{"id":"written-2021-2-45","no":45,"unit":"데이터베이스 구축","q":"DDL(Data Define Language)의 명령어 중 스키마, 도메인, 인덱스 등을 정의할 때 사용하는 SQL문은?","choices":["ALTER","SELECT","CREATE","INSERT"],"ans":3,"rate":69,"exp":{"concept":"DDL(데이터 정의어)은 데이터베이스의 구조를 정의하는 언어로 CREATE, ALTER, DROP, TRUNCATE가 있다. 스키마, 도메인, 테이블, 뷰, 인덱스를 새로 정의할 때는 CREATE를 쓴다.","choices":[{"verdict":"오답","why":"ALTER는 이미 만든 테이블의 정의를 변경하는 DDL 명령이다."},{"verdict":"오답","why":"SELECT는 데이터를 조회하는 DML 명령이다."},{"verdict":"정답","why":"CREATE는 스키마, 도메인, 테이블, 뷰, 인덱스를 정의(생성)하는 DDL 명령이다."},{"verdict":"오답","why":"INSERT는 테이블에 새 행을 삽입하는 DML 명령이다."}],"keywords":[{"term":"DDL","desc":"데이터 정의어: CREATE, ALTER, DROP, TRUNCATE"},{"term":"DML","desc":"데이터 조작어: SELECT, INSERT, UPDATE, DELETE"},{"term":"DCL","desc":"데이터 제어어: GRANT, REVOKE, COMMIT, ROLLBACK"}],"memo":"정의(만들기)는 CREATE, 수정은 ALTER, 삭제는 DROP. DDL은 '틀'을 다룬다."}},{"id":"written-2021-2-46","no":46,"unit":"데이터베이스 구축","q":"테이블 R1, R2에 대하여 다음 SQL문의 결과는?\n<div class=\"q-spec\">\n<span class=\"q-spec__label\">보기</span>\n<pre class=\"q-sql\"><code class=\"language-sql\">(SELECT 학번 FROM R1)\nINTERSECT\n(SELECT 학번 FROM R2)</code></pre>\n<div class=\"q-tbl-title\">[R1 테이블]</div><table class=\"q-tbl is-data\"><thead><tr><th>학번</th><th>학점 수</th></tr></thead><tbody><tr><td>20201111</td><td>15</td></tr><tr><td>20202222</td><td>20</td></tr></tbody></table>\n<div class=\"q-tbl-title\">[R2 테이블]</div><table class=\"q-tbl is-data\"><thead><tr><th>학번</th><th>과목번호</th></tr></thead><tbody><tr><td>20202222</td><td>CS200</td></tr><tr><td>20203333</td><td>CS300</td></tr></tbody></table>\n</div>","choices":["<table class=\"q-tbl is-data\"><thead><tr><th>학번</th><th>학점 수</th><th>과목번호</th></tr></thead><tbody><tr><td>20202222</td><td>20</td><td>CS200</td></tr></tbody></table>","<table class=\"q-tbl is-data\"><thead><tr><th>학번</th></tr></thead><tbody><tr><td>20202222</td></tr></tbody></table>","<table class=\"q-tbl is-data\"><thead><tr><th>학번</th></tr></thead><tbody><tr><td>20201111</td></tr><tr><td>20202222</td></tr><tr><td>20203333</td></tr></tbody></table>","<table class=\"q-tbl is-data\"><thead><tr><th>학번</th><th>학점 수</th><th>과목번호</th></tr></thead><tbody><tr><td>20201111</td><td>15</td><td>NULL</td></tr><tr><td>20202222</td><td>20</td><td>CS200</td></tr><tr><td>20203333</td><td>NULL</td><td>CS300</td></tr></tbody></table>"],"ans":2,"rate":60,"exp":{"concept":"INTERSECT는 두 SELECT 결과에 모두 있는 행만 남기는 교집합 연산이다. R1의 학번은 20201111, 20202222이고 R2의 학번은 20202222, 20203333이므로 공통 값은 20202222 하나다. SELECT 학번만 했으므로 결과는 학번 열 하나, 행 하나다.","choices":[{"verdict":"오답","why":"학번, 학점 수, 과목번호가 모두 있는 결과는 두 테이블을 학번으로 조인한 결과로, 학번만 조회하는 INTERSECT 결과가 아니다."},{"verdict":"정답","why":"두 테이블의 학번 중 공통 값인 20202222만 남은 결과이므로 정답이다."},{"verdict":"오답","why":"20201111, 20202222, 20203333이 모두 나온 것은 합집합(UNION) 결과다."},{"verdict":"오답","why":"NULL이 섞여 모든 행이 나온 것은 완전 외부 조인(FULL OUTER JOIN) 결과다."}],"keywords":[{"term":"INTERSECT","desc":"두 질의 결과의 교집합"},{"term":"UNION","desc":"합집합(중복 제거), UNION ALL은 중복 포함"},{"term":"EXCEPT(MINUS)","desc":"차집합, 앞 결과에만 있는 행"}],"memo":"집합 연산은 결과 열이 SELECT한 열 그대로다. 학번만 뽑았으면 결과에도 학번만 있다."}},{"id":"written-2021-2-47","no":47,"unit":"데이터베이스 구축","q":"데이터베이스 설계 시 물리적 설계 단계에서 수행하는 사항이 아닌 것은?","choices":["레코드 집중의 분석 및 설계","접근 경로 설계","저장 레코드의 양식 설계","목표 DBMS에 맞는 스키마 설계"],"ans":4,"rate":66,"exp":{"concept":"데이터베이스 설계는 요구 분석 → 개념적 설계 → 논리적 설계 → 물리적 설계 → 구현 순서로 진행된다. 논리적 설계는 목표 DBMS의 데이터 모델에 맞게 스키마를 설계하고, 물리적 설계는 저장 레코드 양식, 레코드 집중(클러스터링), 접근 경로(인덱스) 등 실제 저장 방식을 설계한다.","choices":[{"verdict":"오답","why":"레코드 집중(클러스터링)의 분석 및 설계는 물리적 설계에서 한다."},{"verdict":"오답","why":"인덱스 등 접근 경로 설계는 물리적 설계에서 한다."},{"verdict":"오답","why":"저장 레코드의 양식 설계는 물리적 설계에서 한다."},{"verdict":"정답","why":"목표 DBMS에 맞는 스키마 설계는 논리적 설계 단계에서 한다."}],"keywords":[{"term":"개념적 설계","desc":"E-R 다이어그램 작성, DBMS와 무관한 개념 스키마 설계"},{"term":"논리적 설계","desc":"목표 DBMS의 데이터 모델에 맞는 스키마 설계, 정규화"},{"term":"물리적 설계","desc":"저장 레코드 양식, 레코드 집중, 접근 경로 설계"}],"memo":"논리적 설계는 '목표 DBMS에 맞는 스키마', 물리적 설계는 '저장·접근 방법'. DBMS라는 말이 나와도 스키마면 논리적이다."}},{"id":"written-2021-2-48","no":48,"unit":"데이터베이스 구축","q":"릴레이션에서 기본 키를 구성하는 속성은　널(Null)값이나 중복 값을 가질 수 없다는　것을 의미하는 제약조건은?","choices":["참조 무결성","보안 무결성","개체 무결성","정보 무결성"],"ans":3,"rate":80,"exp":{"concept":"무결성 제약조건은 데이터의 정확성을 지키는 규칙이다. 개체 무결성은 기본 키를 이루는 속성이 널(NULL)이나 중복 값을 가질 수 없다는 규칙이고, 참조 무결성은 외래 키 값이 참조하는 테이블의 기본 키 값이거나 NULL이어야 한다는 규칙이다.","choices":[{"verdict":"오답","why":"참조 무결성은 외래 키 값이 참조 테이블의 기본 키 값과 같거나 NULL이어야 한다는 제약조건이다."},{"verdict":"오답","why":"보안 무결성은 표준 무결성 제약조건(개체, 참조, 도메인, 사용자 정의 등)에 들지 않는다."},{"verdict":"정답","why":"기본 키는 NULL이나 중복 값을 가질 수 없다는 제약조건이 개체 무결성이다."},{"verdict":"오답","why":"정보 무결성은 표준 무결성 제약조건의 이름이 아니다."}],"keywords":[{"term":"개체 무결성","desc":"기본 키는 NULL과 중복 값을 가질 수 없음"},{"term":"참조 무결성","desc":"외래 키는 참조 테이블의 기본 키 값이거나 NULL"},{"term":"도메인 무결성","desc":"속성 값은 정의된 도메인 범위 안의 값이어야 함"}],"memo":"기본 키 규칙은 개체 무결성, 외래 키 규칙은 참조 무결성."}},{"id":"written-2021-2-49","no":49,"unit":"데이터베이스 구축","q":"병행제어 기법의 종류가 아닌 것은?","choices":["로킹 기법","시분할 기법","타임 스탬프 기법","다중 버전 기법"],"ans":2,"rate":48,"exp":{"concept":"병행 제어는 여러 트랜잭션이 동시에 실행될 때 데이터의 일관성을 지키도록 실행 순서를 조절하는 것이다. 기법으로 로킹, 타임 스탬프 순서, 다중 버전, 낙관적 검증 기법이 있다.","choices":[{"verdict":"오답","why":"로킹(Locking)은 데이터에 잠금을 걸어 다른 트랜잭션의 접근을 막는 병행 제어 기법이다."},{"verdict":"정답","why":"시분할(Time Sharing)은 CPU 시간을 잘게 나누어 여러 사용자가 번갈아 쓰게 하는 운영체제의 처리 방식으로, 병행 제어 기법이 아니다."},{"verdict":"오답","why":"타임 스탬프 기법은 트랜잭션에 시작 시각(타임 스탬프)을 붙여 그 순서대로 실행하는 병행 제어 기법이다."},{"verdict":"오답","why":"다중 버전 기법은 데이터의 여러 버전을 두고 타임 스탬프에 맞는 버전을 읽게 하는 병행 제어 기법이다."}],"keywords":[{"term":"병행 제어(Concurrency Control)","desc":"동시 실행 트랜잭션 간 일관성을 유지하는 제어"},{"term":"로킹(Locking)","desc":"잠금으로 데이터 접근을 상호 배제"},{"term":"타임 스탬프 순서","desc":"트랜잭션 시작 시각 순서로 실행 순서 결정"},{"term":"낙관적 검증","desc":"일단 실행하고 종료 시점에 검증"}],"memo":"병행 제어 4가지: 로킹, 타임 스탬프, 다중 버전, 낙관적 검증. '시분할'은 운영체제 용어다."}},{"id":"written-2021-2-50","no":50,"unit":"데이터베이스 구축","q":"다음 R1과 R2의 테이블에서 아래의　실행 결과를 얻기 위한 SQL문은?\n<img src=\"data/img/eip_written_20210515_050.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["SELECT 과목번호, 과목이름 FROM RI, R2 WHERE R1.학번 = R2. 학번 AND R1.학과='전자공학' AND R1.이름 = '강남길’;","SELECT 과목번호, 과목이름 FROM RI, R2 WHERE R1.학번 = R2.학번 OR R1.학과='전자공학' OR R1.이름 = '홍길동';","SELECT 과목번호, 과목이름 FROM R1, R2 WHERE R1.학번 = R2.학번 AND R1.학과=‘컴퓨터공학' AND R1.이름 '강남길’;","SELECT 과목번호, 과목이름 FROM R1, R2 WHERE R1.학번 = R2.학번 OR R1.학과='컴퓨터공학' OR R1.이름 = '홍길동';"],"ans":1,"rate":67,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"실행 결과는 C100 컴퓨터구조, C200 데이터베이스 두 행이다. R2에서 C100과 C200을 모두 수강한 학생은 학번 3000(강남길, 전자공학)뿐이다. 따라서 두 테이블을 학번으로 조인하고(R1.학번 = R2.학번), 학과가 전자공학이고 이름이 강남길인 조건을 AND로 연결해야 한다.","choices":[{"verdict":"정답","why":"R1.학번 = R2.학번으로 조인한 뒤 학과 '전자공학', 이름 '강남길'을 AND로 거르면 학번 3000의 두 과목 C100 컴퓨터구조, C200 데이터베이스만 남는다."},{"verdict":"오답","why":"OR로 연결하면 조인 조건이 없어도 전자공학과 학생이나 홍길동이면 R2의 모든 행과 결합되어 운영체제(C300)까지 포함된 많은 행이 나온다."},{"verdict":"오답","why":"강남길은 전자공학과 학생이므로 학과를 컴퓨터공학으로 지정하면 결과가 한 행도 나오지 않는다. 이름 조건에 '='도 빠져 있다."},{"verdict":"오답","why":"OR로 연결하면 컴퓨터공학과 학생이나 홍길동이면 R2의 모든 행과 결합되어 운영체제(C300)까지 포함된 많은 행이 나온다."}],"keywords":[{"term":"조인 조건","desc":"두 테이블의 공통 속성을 같게 묶는 조건, 예: R1.학번 = R2.학번"},{"term":"AND / OR","desc":"AND는 모든 조건을 만족, OR는 하나만 만족해도 선택"},{"term":"카티션 곱","desc":"조인 조건 없이 FROM에 두 테이블을 쓰면 모든 행끼리 결합됨"}],"memo":"조인 조건은 반드시 AND로 다른 조건과 묶는다. OR로 묶으면 카티션 곱이 섞여 결과가 폭증한다."}},{"id":"written-2021-2-51","no":51,"unit":"데이터베이스 구축","q":"다음 관계 대수 중 순수 관계 연산자가 아닌 것은?","choices":["차집합(difference)","프로젝트(project)","조인(join)","디비전 (division)"],"ans":1,"rate":57,"wiki":[{"title":"관계대수","url":"https://itwiki.kr/w/관계대수"}],"exp":{"concept":"관계 대수 연산자는 순수 관계 연산자와 일반 집합 연산자로 나뉜다. 순수 관계 연산자는 릴레이션의 구조를 다루기 위해 따로 만든 연산으로 셀렉트(σ), 프로젝트(π), 조인(⋈), 디비전(÷)이 있다. 합집합, 교집합, 차집합, 카티션 프로덕트는 수학의 집합 연산을 가져온 일반 집합 연산자다.","choices":[{"verdict":"정답","why":"차집합(Difference, −)은 일반 집합 연산자이므로 순수 관계 연산자가 아니다."},{"verdict":"오답","why":"프로젝트(Project, π)는 릴레이션에서 원하는 속성(열)만 뽑는 순수 관계 연산자다."},{"verdict":"오답","why":"조인(Join, ⋈)은 공통 속성을 기준으로 두 릴레이션을 하나로 합치는 순수 관계 연산자다."},{"verdict":"오답","why":"디비전(Division, ÷)은 한 릴레이션이 다른 릴레이션의 모든 값과 관련된 튜플을 찾는 순수 관계 연산자다."}],"keywords":[{"term":"순수 관계 연산자","desc":"셀렉트(σ), 프로젝트(π), 조인(⋈), 디비전(÷)"},{"term":"일반 집합 연산자","desc":"합집합(∪), 교집합(∩), 차집합(−), 카티션 프로덕트(×)"},{"term":"셀렉트(Select, σ)","desc":"조건을 만족하는 튜플(행)을 선택"}],"memo":"순수 관계 연산자는 '셀프조디'(셀렉트·프로젝트·조인·디비전). 집합 이름(합·교·차·곱)이면 일반 집합 연산자다."}},{"id":"written-2021-2-52","no":52,"unit":"데이터베이스 구축","q":"관계형 데이터 모델의 릴레이션에 대한 설명으로 틀린 것은?","choices":["모든 속성 값은 원자 값을 갖는다.","한 릴레이션에 포함된 튜플은 모두 상이하다.","한 릴레이션에 포함된 튜플 사이에는 순서가 없다.","한 릴레이션을 구성하는 속성 사이에는 순서가 존재한다."],"ans":4,"rate":70,"exp":{"concept":"릴레이션(테이블)에는 몇 가지 특징이 있다. 모든 튜플(행)은 서로 다르고, 튜플 사이에 순서가 없으며, 속성(열) 사이에도 순서가 없고, 모든 속성 값은 더 나눌 수 없는 원자 값이다. 출석부의 학생 순서나 열 순서를 바꿔도 같은 정보인 것과 같다.","choices":[{"verdict":"오답","why":"릴레이션의 모든 속성 값은 원자 값(더 이상 분해할 수 없는 값)을 갖는다."},{"verdict":"오답","why":"한 릴레이션에 포함된 튜플은 모두 서로 달라야 하므로 중복 튜플이 없다."},{"verdict":"오답","why":"튜플 사이에는 순서가 없다."},{"verdict":"정답","why":"속성 사이에도 순서가 없다. 속성 사이에 순서가 존재한다는 설명이 틀렸다."}],"keywords":[{"term":"튜플의 유일성","desc":"릴레이션의 모든 튜플은 서로 다름"},{"term":"튜플의 무순서성","desc":"튜플 사이에 순서가 없음"},{"term":"속성의 무순서성","desc":"속성 사이에 순서가 없음"},{"term":"속성의 원자성","desc":"속성 값은 원자 값만 가짐"}],"memo":"릴레이션은 행도 열도 순서가 없다. '순서가 존재한다'가 나오면 틀린 보기다."}},{"id":"written-2021-2-53","no":53,"unit":"데이터베이스 구축","q":"릴레이션 R의 차수가 4이고 카디널리티가 5이며, 릴레이션 S의 차수가 6이고 카디널리티가 7일 때, 두 개의 릴레이션을 카티션 프로덕트한 결과의 새로운 릴레이 션의 차수와 카디널리티는 얼마인가?","choices":["24, 35","24, 12","10, 35","10, 12"],"ans":3,"rate":64,"exp":{"concept":"차수(Degree)는 속성(열)의 수, 카디널리티(Cardinality)는 튜플(행)의 수다. 카티션 프로덕트는 두 릴레이션의 모든 행을 서로 짝지으므로 열은 더하고 행은 곱한다. 차수는 4 + 6 = 10, 카디널리티는 5 × 7 = 35다.","choices":[{"verdict":"오답","why":"차수를 4 × 6 = 24로 곱했으므로 틀리다. 차수는 더한다."},{"verdict":"오답","why":"차수는 곱하고 카디널리티는 더해서 반대로 계산했으므로 틀리다."},{"verdict":"정답","why":"차수 4 + 6 = 10, 카디널리티 5 × 7 = 35이므로 정답이다."},{"verdict":"오답","why":"카디널리티를 5 + 7 = 12로 더했으므로 틀리다. 카디널리티는 곱한다."}],"keywords":[{"term":"차수(Degree)","desc":"릴레이션의 속성(열) 수"},{"term":"카디널리티(Cardinality)","desc":"릴레이션의 튜플(행) 수"},{"term":"카티션 프로덕트(×)","desc":"두 릴레이션의 모든 튜플을 짝지은 결과, 차수는 합·카디널리티는 곱"}],"memo":"카티션 프로덕트: 열은 '옆으로 붙이니' 더하고, 행은 '모든 짝'이니 곱한다."}},{"id":"written-2021-2-54","no":54,"unit":"데이터베이스 구축","q":"속성(attribute)에 대한 설명으로 틀린 것은?","choices":["속성은 개체의 특성을 기술한다.","속성은 데이터베이스를 구성하는 가장 작은 논리적 단위이다.","속성은 파일 구조상 데이터 항목 또는 데이터 필드에 해당된다.","속성의 수를 \"cardinality\" 라고 한다."],"ans":4,"rate":71,"exp":{"concept":"속성(Attribute)은 개체의 특성을 나타내는 데이터베이스의 가장 작은 논리적 단위로, 테이블의 열(컬럼)이고 파일 구조의 필드에 해당한다. 속성의 수는 차수(Degree), 튜플의 수는 카디널리티(Cardinality)라고 한다.","choices":[{"verdict":"오답","why":"속성은 개체의 특성(이름, 학번 등)을 기술한다."},{"verdict":"오답","why":"속성은 데이터베이스를 구성하는 가장 작은 논리적 단위다."},{"verdict":"오답","why":"속성은 파일 구조상의 데이터 항목 또는 데이터 필드에 해당한다."},{"verdict":"정답","why":"속성의 수는 차수(Degree)라고 한다. 카디널리티(Cardinality)는 튜플의 수다."}],"keywords":[{"term":"속성(Attribute)","desc":"개체의 특성, 테이블의 열, DB의 가장 작은 논리적 단위"},{"term":"차수(Degree)","desc":"속성의 수"},{"term":"카디널리티(Cardinality)","desc":"튜플의 수"},{"term":"도메인(Domain)","desc":"한 속성이 가질 수 있는 값의 범위"}],"memo":"Degree는 열(세로줄) 개수, Cardinality는 행(가로줄) 개수. '카'디널리티는 '가'로줄 수로 연결해 외운다."}},{"id":"written-2021-2-55","no":55,"unit":"데이터베이스 구축","q":"다음 SQL 문에서 ( ) 안에 들어갈 내용으로 옳은 것은?\n<img src=\"data/img/eip_written_20210515_055.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["SET","FROM","INTO","IN"],"ans":1,"rate":75,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"UPDATE 문은 'UPDATE 테이블 SET 열 = 값 WHERE 조건;' 형식으로 기존 행의 값을 바꾼다. 문제의 문장은 인사급여 테이블에서 성명이 '홍길동'인 행의 호봉을 15로 바꾸는 것이므로 빈칸에는 SET이 들어간다.","choices":[{"verdict":"정답","why":"SET은 UPDATE 문에서 변경할 열과 값을 지정하는 키워드로, 빈칸에 들어갈 내용이다."},{"verdict":"오답","why":"FROM은 SELECT, DELETE 문에서 대상 테이블을 지정하는 키워드다."},{"verdict":"오답","why":"INTO는 INSERT INTO 테이블 형식으로 INSERT 문에서 쓰는 키워드다."},{"verdict":"오답","why":"IN은 WHERE 절에서 값이 목록 안에 있는지 검사하는 연산자다."}],"keywords":[{"term":"UPDATE","desc":"UPDATE 테이블 SET 열=값 WHERE 조건;"},{"term":"INSERT","desc":"INSERT INTO 테이블(열) VALUES(값);"},{"term":"DELETE","desc":"DELETE FROM 테이블 WHERE 조건;"}],"memo":"DML 짝꿍: INSERT-INTO, UPDATE-SET, DELETE-FROM."}},{"id":"written-2021-2-56","no":56,"unit":"데이터베이스 구축","q":"관계 데이터베이스 모델에서 차수(Degree)의 의미는?","choices":["튜플의 수","테이블의 수","데이터베이스의 수","애트리뷰트의 수"],"ans":4,"rate":69,"exp":{"concept":"관계 데이터베이스에서 차수(Degree)는 한 릴레이션을 이루는 애트리뷰트(속성, 열)의 수다. 반대로 튜플(행)의 수는 카디널리티(Cardinality)라고 한다.","choices":[{"verdict":"오답","why":"튜플의 수는 카디널리티(Cardinality)다."},{"verdict":"오답","why":"테이블의 수는 차수와 관계가 없다."},{"verdict":"오답","why":"데이터베이스의 수는 차수와 관계가 없다."},{"verdict":"정답","why":"차수는 애트리뷰트(속성)의 수다."}],"keywords":[{"term":"차수(Degree)","desc":"애트리뷰트(속성) 수"},{"term":"카디널리티(Cardinality)","desc":"튜플 수"},{"term":"애트리뷰트(Attribute)","desc":"릴레이션의 열, 개체의 특성"}],"memo":"차수=열 수, 카디널리티=행 수. 53번 같은 계산 문제와 짝으로 나온다."}},{"id":"written-2021-2-57","no":57,"unit":"데이터베이스 구축","q":"개체-관계 모델(E-R)의 그래픽 표현으로 옳지 않은 것은?","choices":["개체타입 – 사각형","속성 - 원형","관계타입 - 마름모","연결 - 삼각형"],"ans":4,"rate":86,"exp":{"concept":"E-R 다이어그램은 개체, 속성, 관계를 기호로 그린다. 개체 타입은 사각형, 속성은 타원(원형), 관계 타입은 마름모, 이들을 잇는 연결(링크)은 선으로 나타낸다.","choices":[{"verdict":"오답","why":"개체 타입은 사각형으로 표현한다."},{"verdict":"오답","why":"속성은 타원(원형)으로 표현한다."},{"verdict":"오답","why":"관계 타입은 마름모로 표현한다."},{"verdict":"정답","why":"연결(링크)은 선으로 표현한다. 삼각형은 E-R 다이어그램의 표준 기호가 아니다."}],"keywords":[{"term":"개체 타입","desc":"사각형"},{"term":"관계 타입","desc":"마름모"},{"term":"속성","desc":"타원, 기본 키 속성은 밑줄 친 타원"},{"term":"다중값 속성","desc":"이중 타원"}],"memo":"사각형(개체)-마름모(관계)-타원(속성)-선(연결). 삼각형은 없다."}},{"id":"written-2021-2-58","no":58,"unit":"데이터베이스 구축","q":"트랜잭션의 실행이 실패하였음을 알리는 연산자로 트랜잭션이 수행한 결과를 원래의 상태로 원상 복귀 시키는 연산은?","choices":["COMMIT 연산","BACKUP 연산","LOG 연산","ROLLBACK 연산"],"ans":4,"rate":94,"exp":{"concept":"트랜잭션은 모두 성공하거나 모두 취소되어야 하는 작업 단위다. 성공하면 COMMIT으로 결과를 확정하고, 실패하면 ROLLBACK으로 그 트랜잭션이 바꾼 내용을 모두 되돌려 원래 상태로 복구한다.","choices":[{"verdict":"오답","why":"COMMIT은 트랜잭션이 성공적으로 끝났을 때 변경 내용을 데이터베이스에 영구히 반영하는 연산이다."},{"verdict":"오답","why":"BACKUP은 데이터를 복사해 두는 작업으로, 트랜잭션 제어 연산이 아니다."},{"verdict":"오답","why":"LOG는 데이터베이스 변경 내역을 기록하는 것으로, 실패를 알리고 원상 복귀하는 연산이 아니다."},{"verdict":"정답","why":"ROLLBACK은 트랜잭션 실행이 실패했을 때 수행한 결과를 취소해 원래 상태로 되돌리는 연산이다."}],"keywords":[{"term":"COMMIT","desc":"트랜잭션 성공, 변경 내용 확정"},{"term":"ROLLBACK","desc":"트랜잭션 실패, 변경 내용 취소·원상 복귀"},{"term":"SAVEPOINT","desc":"ROLLBACK할 중간 지점을 지정"},{"term":"원자성(Atomicity)","desc":"트랜잭션은 전부 실행되거나 전혀 실행되지 않아야 함"}],"memo":"Roll back은 '되감기'. 실패하면 되감아 원래대로."}},{"id":"written-2021-2-59","no":59,"unit":"데이터베이스 구축","q":"데이터 속성 간의 종속성에 대한 엄밀한 고려없이 잘못 설계된 데이터베이스에서는 데이터 처리 연산 수행 시 각종 이상 현상이 발생할 수 있는데, 이러한 이상 현상이 아닌 것은?","choices":["검색 이상","삽입 이상","삭제 이상","갱신 이상"],"ans":1,"rate":65,"exp":{"concept":"정규화가 덜 된 테이블에 데이터를 넣고, 지우고, 고칠 때 생기는 문제를 이상(Anomaly) 현상이라고 한다. 이상 현상에는 삽입 이상, 삭제 이상, 갱신 이상의 세 가지가 있으며, 정규화로 해결한다.","choices":[{"verdict":"정답","why":"검색(조회)은 데이터를 바꾸지 않으므로 이상 현상이 생기지 않는다. 검색 이상이라는 분류는 없다."},{"verdict":"오답","why":"삽입 이상은 원하지 않는 값까지 함께 넣어야 하거나 일부 값만 넣을 수 없는 현상이다."},{"verdict":"오답","why":"삭제 이상은 한 행을 지울 때 필요한 다른 정보까지 함께 지워지는 연쇄 삭제 현상이다."},{"verdict":"오답","why":"갱신 이상은 중복된 값 중 일부만 고쳐져 데이터가 서로 맞지 않게 되는 현상이다."}],"keywords":[{"term":"삽입 이상","desc":"불필요한 값을 함께 넣어야 삽입 가능"},{"term":"삭제 이상","desc":"삭제 시 필요한 정보까지 함께 삭제"},{"term":"갱신 이상","desc":"중복 데이터 일부만 수정되어 불일치 발생"},{"term":"정규화(Normalization)","desc":"이상 현상을 없애기 위해 릴레이션을 분해하는 과정"}],"memo":"이상 현상은 '삽삭갱' 세 가지. 데이터를 바꾸는 연산에서만 생긴다."}},{"id":"written-2021-2-60","no":60,"unit":"데이터베이스 구축","q":"제3정규형 (3NF)에서 BCNF(Boyce-Codd Normal Form)가 되기 위한 조건은?","choices":["결정자가 후보키가 아닌 함수 종속 제거","이행적 함수 종속 제거","부분적 함수 종속 제거","원자값이 아닌 도메인 분해"],"ans":1,"rate":73,"exp":{"concept":"정규화는 단계별로 종속성을 하나씩 없앤다. 1NF는 원자 값으로 분해, 2NF는 부분 함수 종속 제거, 3NF는 이행 함수 종속 제거, BCNF는 결정자이면서 후보키가 아닌 것을 제거, 4NF는 다치 종속 제거, 5NF는 조인 종속 제거다. 3NF에서 BCNF로 가려면 모든 결정자가 후보키가 되게 해야 한다.","choices":[{"verdict":"정답","why":"결정자가 후보키가 아닌 함수 종속을 제거하면 BCNF가 된다."},{"verdict":"오답","why":"이행적 함수 종속 제거는 2NF에서 3NF로 가는 조건이다."},{"verdict":"오답","why":"부분적 함수 종속 제거는 1NF에서 2NF로 가는 조건이다."},{"verdict":"오답","why":"원자 값이 아닌 도메인 분해는 비정규 릴레이션을 1NF로 만드는 조건이다."}],"keywords":[{"term":"2NF","desc":"부분 함수 종속 제거"},{"term":"3NF","desc":"이행 함수 종속 제거"},{"term":"BCNF","desc":"결정자이면서 후보키가 아닌 것 제거, 모든 결정자가 후보키"},{"term":"4NF·5NF","desc":"다치 종속 제거, 조인 종속 제거"}],"memo":"'도부이결다조'(도메인 원자화·부분·이행·결정자·다치·조인) 순서로 1NF부터 5NF까지 외운다."}},{"id":"written-2021-2-61","no":61,"unit":"프로그래밍 언어 활용","q":"다음 설명에 해당하는 방식은?\n<img src=\"data/img/eip_written_20210515_061.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["STA","Collision Domain","CSMA/CA","CSMA/CD"],"ans":3,"rate":61,"wiki":[{"title":"CSMA/CA","url":"https://itwiki.kr/w/CSMA/CA"}],"exp":{"concept":"무선 랜은 충돌을 직접 감지하기 어려워 충돌을 미리 피하는 CSMA/CA(Carrier Sense Multiple Access / Collision Avoidance) 방식을 쓴다. 매체가 비어 있는지 확인한 뒤 임의의 시간만큼 더 기다렸다가 전송하고, 확인 신호(ACK)를 주고받는다. 유선 이더넷은 충돌을 감지하는 CSMA/CD를 쓴다.","choices":[{"verdict":"오답","why":"STA(Station)는 무선 랜에서 통신에 참여하는 단말(스테이션)을 뜻하며, 전송 방식이 아니다."},{"verdict":"오답","why":"충돌 도메인(Collision Domain)은 동시에 전송하면 충돌이 일어날 수 있는 네트워크 범위를 뜻하며, 전송 방식이 아니다."},{"verdict":"정답","why":"무선 랜에서 매체가 비었는지 확인하고 임의 시간 기다린 뒤 전송해 충돌을 회피하는 방식은 CSMA/CA다."},{"verdict":"오답","why":"CSMA/CD는 유선 이더넷에서 전송 중 충돌을 감지(Detection)하면 전송을 멈추고 일정 시간 뒤 재전송하는 방식이다."}],"keywords":[{"term":"CSMA/CA","desc":"무선 랜(IEEE 802.11)의 충돌 회피 방식"},{"term":"CSMA/CD","desc":"유선 이더넷(IEEE 802.3)의 충돌 감지 방식"},{"term":"충돌 도메인","desc":"충돌이 발생할 수 있는 네트워크 영역"}],"memo":"무선은 Avoidance(피하기), 유선은 Detection(감지). '무CA 유CD'로 외운다."}},{"id":"written-2021-2-62","no":62,"unit":"프로그래밍 언어 활용","q":"다음 중 가장 약한 결합도(Coupling)는?","choices":["Common Coupling","Content Coupling","External Coupling","Stamp Coupling"],"ans":4,"rate":56,"wiki":[{"title":"결합도","url":"https://itwiki.kr/w/결합도"},{"title":"모듈화","url":"https://itwiki.kr/w/모듈화"}],"exp":{"concept":"결합도(Coupling)는 모듈끼리 얼마나 의존하는지를 나타내며, 약할수록 좋은 설계다. 약한 것부터 자료(Data) < 스탬프(Stamp) < 제어(Control) < 외부(External) < 공통(Common) < 내용(Content) 결합도 순서다. 보기 중 가장 약한 것은 스탬프 결합도다.","choices":[{"verdict":"오답","why":"공통 결합도(Common Coupling)는 여러 모듈이 공통 데이터 영역(전역 변수)을 함께 쓰는 결합도로, 두 번째로 강하다."},{"verdict":"오답","why":"내용 결합도(Content Coupling)는 한 모듈이 다른 모듈의 내부 기능이나 자료를 직접 참조·수정하는 결합도로, 가장 강하다."},{"verdict":"오답","why":"외부 결합도(External Coupling)는 한 모듈이 선언한 변수를 외부의 다른 모듈에서 참조하는 결합도로, 스탬프보다 강하다."},{"verdict":"정답","why":"스탬프 결합도(Stamp Coupling)는 배열이나 레코드 같은 자료 구조를 인터페이스로 넘기는 결합도로, 보기 중 가장 약하다."}],"keywords":[{"term":"자료 결합도(Data)","desc":"단순 값만 매개변수로 전달, 가장 약함"},{"term":"스탬프 결합도(Stamp)","desc":"배열·레코드 등 자료 구조 전달"},{"term":"제어 결합도(Control)","desc":"제어 신호(플래그)를 전달해 상대 모듈의 흐름을 제어"},{"term":"내용 결합도(Content)","desc":"다른 모듈 내부를 직접 참조, 가장 강함"}],"memo":"결합도 약→강은 '자스제외공내'(자료·스탬프·제어·외부·공통·내용)."}},{"id":"written-2021-2-63","no":63,"unit":"프로그래밍 언어 활용","q":"다음 C언어 프로그램이 실행되었을 때의 결과는?\n<img src=\"data/img/eip_written_20210515_063.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["3","4","7","10"],"ans":3,"rate":69,"exp":{"concept":"|는 비트 단위 OR 연산자로, 두 수를 2진수로 바꾸어 같은 자리 중 하나라도 1이면 1을 만든다. a = 4는 2진수 0100, b = 7은 0111이므로 0100 | 0111 = 0111 = 7이다. printf(\"%d\", c)는 7을 출력한다.","choices":[{"verdict":"오답","why":"3은 4 ^ 7(비트 XOR, 0100 ^ 0111 = 0011)의 결과로, OR 결과가 아니다."},{"verdict":"오답","why":"4는 4 & 7(비트 AND, 0100 & 0111 = 0100)의 결과로, OR 결과가 아니다."},{"verdict":"정답","why":"0100 | 0111 = 0111이므로 c = 7이 출력된다."},{"verdict":"오답","why":"10은 4와 7의 비트 OR 연산으로 나올 수 없는 값이다."}],"keywords":[{"term":"비트 OR(|)","desc":"같은 자리 비트 중 하나라도 1이면 1"},{"term":"비트 AND(&)","desc":"같은 자리 비트가 모두 1일 때만 1"},{"term":"비트 XOR(^)","desc":"같은 자리 비트가 서로 다를 때 1"},{"term":"논리 OR(||)","desc":"참·거짓만 따지며 결과는 1 또는 0"}],"memo":"비트 연산은 2진수로 세로로 맞춰 적고 자리별로 계산한다. | 하나는 비트 OR, || 둘은 논리 OR."}},{"id":"written-2021-2-64","no":64,"unit":"프로그래밍 언어 활용","q":"다음 파이썬(Python) 프로그램이 실행되었을 때의 결과는?\n<img src=\"data/img/eip_written_20210515_064.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["0","2","4","6"],"ans":4,"rate":80,"exp":{"concept":"파이썬 클래스의 메소드는 첫 번째 매개변수로 자기 자신(보통 self라고 쓰며, 이 문제에서는 sel)을 받는다. a.setdata(4, 2)를 호출하면 a.fir = 4, a.sec = 2가 저장되고, a.add()는 4 + 2 = 6을 돌려주어 print가 6을 출력한다.","choices":[{"verdict":"오답","why":"0은 이 코드에서 나올 수 없는 값이다. add는 저장된 4와 2를 더한다."},{"verdict":"오답","why":"2는 4 - 2의 결과로, add 메소드는 더하므로 틀리다."},{"verdict":"오답","why":"4는 fir 값만 출력한 경우로, 이 코드의 결과가 아니다."},{"verdict":"정답","why":"setdata로 fir = 4, sec = 2가 저장되고 add가 4 + 2 = 6을 반환하므로 6이 출력된다."}],"keywords":[{"term":"self","desc":"메소드가 호출된 객체 자신을 가리키는 첫 번째 매개변수(이름은 관례일 뿐)"},{"term":"인스턴스 변수","desc":"self.변수 형태로 객체마다 따로 저장되는 변수"},{"term":"메소드 호출","desc":"a.setdata(4, 2)는 FourCal.setdata(a, 4, 2)와 같음"}],"memo":"self 자리의 이름이 sel이든 무엇이든 첫 번째 매개변수는 객체 자신이다. 호출할 때 인자 개수는 하나 적다."}},{"id":"written-2021-2-65","no":65,"unit":"프로그래밍 언어 활용","q":"교착상태의 해결 방법 중 은행원 알고리즘(Banker's Algorithm)이 해당되는 기법은?","choices":["Detection","Avoidance","Recovery","Prevention"],"ans":2,"rate":68,"wiki":[{"title":"교착상태","url":"https://itwiki.kr/w/교착상태"}],"exp":{"concept":"교착상태(Deadlock) 해결 방법은 예방(Prevention), 회피(Avoidance), 발견(Detection), 회복(Recovery)이다. 은행원 알고리즘은 자원을 할당하기 전에 시스템이 안전 상태를 유지하는지 검사해, 안전할 때만 할당함으로써 교착상태를 피하는 회피 기법이다. 은행이 대출해 줘도 모든 고객 인출 요구를 감당할 수 있을 때만 빌려주는 것과 같다.","choices":[{"verdict":"오답","why":"발견(Detection)은 교착상태가 일어났는지 자원 할당 그래프 등으로 검사해 찾아내는 기법이다."},{"verdict":"정답","why":"회피(Avoidance)는 안전 상태를 유지하도록 자원 할당을 결정하는 기법으로, 은행원 알고리즘이 대표적이다."},{"verdict":"오답","why":"회복(Recovery)은 교착상태에 빠진 프로세스를 종료하거나 자원을 빼앗아 해결하는 기법이다."},{"verdict":"오답","why":"예방(Prevention)은 교착상태 발생 조건 4가지(상호 배제, 점유와 대기, 비선점, 환형 대기) 중 하나를 없애 처음부터 막는 기법이다."}],"keywords":[{"term":"은행원 알고리즘","desc":"다익스트라가 제안한 교착상태 회피 기법, 안전 상태일 때만 자원 할당"},{"term":"안전 상태(Safe State)","desc":"모든 프로세스가 정상 종료될 수 있는 자원 할당 순서가 존재하는 상태"},{"term":"교착상태 발생 조건","desc":"상호 배제, 점유와 대기, 비선점, 환형 대기"}],"memo":"은행원 알고리즘은 '회피'. 예방은 조건 제거, 회피는 안전 상태 검사."}},{"id":"written-2021-2-66","no":66,"unit":"프로그래밍 언어 활용","q":"CIDR(Classless Inter-Domain Routing) 표기로 203.241.132.82/27과 같이 사용되었다면, 해당 주소의 서브넷 마스크(subnet mask)는?","choices":["255.255.255.0","255.255.255.224","255.255.255.240","255.255.255.248"],"ans":2,"rate":63,"exp":{"concept":"CIDR 표기에서 / 뒤의 숫자는 서브넷 마스크 앞부분에 1이 몇 개인지를 뜻한다. /27이면 앞 24비트(255.255.255)에 이어 마지막 옥텟의 앞 3비트가 1이다. 마지막 옥텟 11100000은 128 + 64 + 32 = 224이므로 서브넷 마스크는 255.255.255.224다.","choices":[{"verdict":"오답","why":"255.255.255.0은 /24(1이 24개)의 마스크다."},{"verdict":"정답","why":"/27은 마지막 옥텟이 11100000 = 224이므로 255.255.255.224다."},{"verdict":"오답","why":"255.255.255.240은 마지막 옥텟이 11110000인 /28의 마스크다."},{"verdict":"오답","why":"255.255.255.248은 마지막 옥텟이 11111000인 /29의 마스크다."}],"keywords":[{"term":"CIDR","desc":"클래스 구분 없이 /비트 수로 네트워크 부분을 표기하는 방식"},{"term":"서브넷 마스크","desc":"IP 주소에서 네트워크 부분을 1, 호스트 부분을 0으로 표시한 값"},{"term":"/27","desc":"255.255.255.224, 서브넷당 주소 32개(호스트 30개)"}],"memo":"마지막 옥텟 값: /25=128, /26=192, /27=224, /28=240, /29=248, /30=252."}},{"id":"written-2021-2-67","no":67,"unit":"프로그래밍 언어 활용","q":"다음 JAVA 프로그램이 실행되었을 때의 결과는?\n<img src=\"data/img/eip_written_20210515_067.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["5, 5, 5","5, 6, 5","6, 5, 5","5, 6, 4"],"ans":1,"rate":58,"exp":{"concept":"++, --가 변수 뒤에 붙으면(후위) 현재 값을 먼저 쓰고 나중에 바꾸고, 앞에 붙으면(전위) 먼저 바꾼 뒤 그 값을 쓴다. y = x++에서 y에 5가 들어가고 x는 6이 된다. z = --x에서 x가 먼저 5로 줄고 z에 5가 들어간다. 따라서 x, y, z는 모두 5이고 \"5,5,5\"가 출력된다.","choices":[{"verdict":"정답","why":"y = x++로 y = 5, x = 6, 이어서 z = --x로 x = 5, z = 5가 되어 5, 5, 5가 출력된다."},{"verdict":"오답","why":"y = x++는 후위 증가라 y에는 증가 전 값 5가 들어가므로 y = 6이 될 수 없다."},{"verdict":"오답","why":"z = --x에서 x가 6에서 5로 감소하므로 마지막 x는 6이 아니라 5다."},{"verdict":"오답","why":"z = --x는 x가 6에서 5로 줄어든 값을 대입하므로 z = 4가 될 수 없고, y도 6이 아니다."}],"keywords":[{"term":"후위 증감(x++, x--)","desc":"현재 값을 먼저 사용한 뒤 증감"},{"term":"전위 증감(++x, --x)","desc":"먼저 증감한 뒤 그 값을 사용"},{"term":"문자열 연결","desc":"Java에서 숫자 + \",\"는 문자열로 이어 붙여 출력"}],"memo":"++가 뒤에 있으면 '쓰고 나서 더하기', 앞에 있으면 '더하고 나서 쓰기'."}},{"id":"written-2021-2-68","no":68,"unit":"프로그래밍 언어 활용","q":"프로세스 적재 정책과 관련한 설명으로 틀린 것은?","choices":["반복, 스택, 부프로그램은 시간 지역성(Temporal Locality)과 관련이 있다.","공간 지역성(Spatial Locality)은 프로세스가 어떤 페이지를 참조했다면 이후 가상주소공간상 그 페이지와 인접한 페이지들을 참조할 가능성이 높음을 의미한다.","일반적으로 페이지 교환에 보내는 시간보다 프로세스 수행에 보내는 시간이 더 크면 스레싱(Thrashing)이 발생한다.","스레싱(Thrashing) 현상을 방지하기 위해서는 각 프로세스가 필요로 하는 프레임을 제공할 수 있어야 한다."],"ans":3,"rate":61,"wiki":[{"title":"스레싱","url":"https://itwiki.kr/w/스레싱"}],"exp":{"concept":"지역성(Locality)은 프로세스가 일부 페이지만 집중적으로 참조하는 성질이다. 시간 지역성은 최근 참조한 곳을 곧 다시 참조하는 것(반복문, 스택, 부프로그램 등), 공간 지역성은 참조한 곳 근처를 참조하는 것(배열 순회, 순차 코드 등)이다. 스레싱(Thrashing)은 페이지 교체가 너무 잦아 프로세스 실행보다 페이지 교환에 시간을 더 많이 쓰는 현상이다.","choices":[{"verdict":"오답","why":"반복, 스택, 부프로그램은 같은 위치를 반복해 참조하므로 시간 지역성과 관련이 있다."},{"verdict":"오답","why":"공간 지역성은 어떤 페이지를 참조하면 그 근처 페이지를 참조할 가능성이 높다는 성질로, 맞는 설명이다."},{"verdict":"정답","why":"스레싱은 페이지 교환에 쓰는 시간이 프로세스 수행 시간보다 더 클 때 발생한다. 보기는 두 시간을 반대로 설명했다."},{"verdict":"오답","why":"각 프로세스가 필요한 만큼의 프레임(워킹 셋)을 제공하면 스레싱을 방지할 수 있다."}],"keywords":[{"term":"시간 지역성","desc":"최근 참조한 기억 장소를 곧 다시 참조(반복문, 스택, 부프로그램, 카운팅·집계 변수)"},{"term":"공간 지역성","desc":"참조한 곳 근처를 참조(배열 순회, 순차 코드 실행)"},{"term":"스레싱(Thrashing)","desc":"페이지 부재가 과도해 실행보다 페이지 교체에 시간을 더 쓰는 현상"},{"term":"워킹 셋(Working Set)","desc":"프로세스가 일정 시간 동안 자주 참조하는 페이지 집합"}],"memo":"스레싱은 '일보다 짐 옮기기(페이지 교환)에 더 바쁜' 상태다."}},{"id":"written-2021-2-69","no":69,"unit":"프로그래밍 언어 활용","q":"프레임워크(Framework)에 대한 설명으로 옳은 것은?","choices":["소프트웨어 구성에 필요한 기본 구조를 제공함으로써 재사용이 가능하게 해준다","소프트웨어 개발 시 구조가 잡혀 있기 때문에 확장이 불가능하다.","소프트웨어 아키텍처(Architecture)와 동일한 개념이다.","모듈화(Modularity)가 불가능하다."],"ans":1,"rate":62,"wiki":[{"title":"프레임워크","url":"https://itwiki.kr/w/프레임워크"}],"exp":{"concept":"프레임워크는 소프트웨어 개발에 필요한 기본 구조와 공통 기능을 미리 만들어 둔 반제품이다. 개발자는 정해진 구조 위에 필요한 부분만 채우므로 재사용성이 높고, 모듈화와 확장이 가능하다. Spring, Django 등이 대표적이다.","choices":[{"verdict":"정답","why":"프레임워크는 소프트웨어 구성에 필요한 기본 구조를 제공해 재사용이 가능하게 해 준다."},{"verdict":"오답","why":"프레임워크는 확장성을 특징으로 하므로 확장이 불가능하다는 설명은 틀리다."},{"verdict":"오답","why":"소프트웨어 아키텍처는 시스템 전체 구조에 대한 설계이고, 프레임워크는 그 구조를 구현해 재사용할 수 있게 만든 반제품 소프트웨어로 같은 개념이 아니다."},{"verdict":"오답","why":"프레임워크는 모듈화를 특징으로 하므로 모듈화가 불가능하다는 설명은 틀리다."}],"keywords":[{"term":"프레임워크(Framework)","desc":"기본 구조와 공통 기능을 제공하는 재사용 가능한 반제품 소프트웨어"},{"term":"프레임워크 특징","desc":"모듈화, 재사용성, 확장성, 제어의 역흐름"},{"term":"제어의 역흐름(IoC)","desc":"개발자 코드가 아니라 프레임워크가 흐름을 제어하고 개발자 코드를 호출함"}],"memo":"프레임워크 특징 '모재확역'(모듈화·재사용성·확장성·제어의 역흐름). '불가능'이 붙은 보기는 모두 틀리다."}},{"id":"written-2021-2-70","no":70,"unit":"프로그래밍 언어 활용","q":"다음 JAVA 프로그램이 실행되었을 때의 결과는?\n<img src=\"data/img/eip_written_20210515_070.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["2","3","4","5"],"ans":1,"rate":56,"exp":{"concept":"do-while 문은 조건을 나중에 검사하므로 조건이 처음부터 거짓이어도 본문을 최소 한 번 실행한다. cnt = 0에서 do 블록이 실행되어 cnt = 1이 되고, while (cnt < 0)은 1 < 0이 거짓이라 반복이 끝난다. 이어서 if (cnt == 1)이 참이므로 cnt++로 cnt = 2가 되고, 2가 출력된다.","choices":[{"verdict":"정답","why":"do 블록이 한 번 실행되어 cnt = 1, if (cnt == 1)이 참이라 cnt++로 2가 출력된다."},{"verdict":"오답","why":"3은 do 블록이 실행되지 않아 cnt = 0인 상태로 else(cnt + 3)를 실행했을 때의 값이다. do-while은 최소 한 번 실행되므로 틀리다."},{"verdict":"오답","why":"4는 cnt = 1인 상태에서 else(cnt + 3)를 실행했을 때의 값이다. cnt == 1은 참이므로 else로 가지 않는다."},{"verdict":"오답","why":"5는 이 코드의 실행 흐름에서 나올 수 없는 값이다."}],"keywords":[{"term":"do-while","desc":"본문을 먼저 실행하고 조건을 나중에 검사, 최소 1회 실행"},{"term":"while","desc":"조건을 먼저 검사, 처음부터 거짓이면 한 번도 실행하지 않음"},{"term":"printf(Java)","desc":"System.out.printf로 C와 같은 서식 지정 출력"}],"memo":"do-while은 '일단 하고 본다'. 조건이 거짓이어도 한 번은 돈다."}},{"id":"written-2021-2-71","no":71,"unit":"프로그래밍 언어 활용","q":"리눅스 Bash 쉘(Shell)에서 export와 관련한 설명으로 틀린 것은?","choices":["변수를 출력하고자 할 때는 export를 사용해야 한다.","export가 매개변수 없이 쓰일 경우 현재 설정된 환경변수들이 출력된다.","사용자가 생성하는 변수는 export 명령어 표시하지 않는 한 현재 쉘에 국한된다.","변수를 export 시키면 전역(Global)변수처럼 되어 끝까지 기억된다."],"ans":1,"rate":46,"exp":{"concept":"Bash에서 그냥 만든 변수는 현재 셸에서만 쓰이는 지역 변수다. export를 붙이면 환경 변수가 되어 그 셸에서 실행하는 하위 프로세스(자식 셸, 프로그램)에도 전달된다. 변수 값을 화면에 출력하는 것은 echo의 역할이다.","choices":[{"verdict":"정답","why":"변수 값을 출력할 때는 echo(예: echo $변수)를 쓴다. export는 변수를 환경 변수로 지정하는 명령으로, 출력용 명령이 아니다."},{"verdict":"오답","why":"export를 매개변수 없이 실행하면 현재 설정된(내보낸) 환경 변수 목록이 출력된다."},{"verdict":"오답","why":"사용자가 만든 변수는 export하지 않으면 현재 셸에서만 쓸 수 있다."},{"verdict":"오답","why":"export한 변수는 전역 변수처럼 하위 프로세스에도 전달되어 셸이 끝날 때까지 유지된다."}],"keywords":[{"term":"export","desc":"셸 변수를 환경 변수로 지정해 하위 프로세스에 전달"},{"term":"echo","desc":"문자열이나 변수 값을 화면에 출력"},{"term":"환경 변수","desc":"셸과 그 하위 프로세스가 함께 쓰는 변수(예: PATH, HOME)"}],"memo":"보여 주기는 echo, 내보내기(전역화)는 export."}},{"id":"written-2021-2-72","no":72,"unit":"프로그래밍 언어 활용","q":"다음 C언어 프로그램이 실행되었을 때의 결과는?\n<img src=\"data/img/eip_written_20210515_072.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["1","11","66","98"],"ans":3,"rate":72,"exp":{"concept":"C에서 문자는 내부적으로 아스키(ASCII) 코드 정수로 저장된다. 'A'의 아스키 코드는 65이므로 'A' + 1 = 66이고, char a에 66이 저장된다. printf의 %d는 정수로 출력하므로 문자 'B'가 아니라 66이 출력된다.","choices":[{"verdict":"오답","why":"1은 'A'의 값을 0으로 잘못 본 경우로, 'A'는 65이므로 틀리다."},{"verdict":"오답","why":"11은 이 코드의 결과로 나올 수 없는 값이다."},{"verdict":"정답","why":"'A'(65) + 1 = 66이 a에 저장되고 %d로 정수 66이 출력된다."},{"verdict":"오답","why":"98은 소문자 'b'의 아스키 코드다. 대문자 'A'에 1을 더한 값은 66이다."}],"keywords":[{"term":"ASCII 코드","desc":"'A'=65, 'a'=97, '0'=48"},{"term":"%d와 %c","desc":"%d는 정수로, %c는 문자로 출력"},{"term":"문자 연산","desc":"문자에 정수를 더하면 아스키 코드 값으로 계산됨"}],"memo":"'A'=65, 'a'=97(대문자+32), '0'=48. 이 셋은 외워 둔다."}},{"id":"written-2021-2-73","no":73,"unit":"프로그래밍 언어 활용","q":"다음 C언어 프로그램이 실행되었을 때의 결과는?\n<img src=\"data/img/eip_written_20210515_073.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["55","77","121","132"],"ans":3,"rate":64,"exp":{"concept":"2차원 배열은 메모리에 한 줄로 이어 저장된다. a[2][2] = {{11, 22}, {44, 55}}는 메모리에 11, 22, 44, 55 순서로 놓인다. p = a[0]이면 p는 11을 가리키므로 *(p + 0) = 11, *(p + 1) = 22, *(p + 2) = 44, *(p + 3) = 55다. for문은 i = 1, 2, 3만 돌므로 sum = 22 + 44 + 55 = 121이다.","choices":[{"verdict":"오답","why":"55는 마지막 원소 하나의 값이다. i = 1부터 3까지 세 원소를 더하므로 틀리다."},{"verdict":"오답","why":"77은 i = 0부터 2까지(11 + 22 + 44) 더한 값이다. 반복은 i = 1부터 시작하므로 틀리다."},{"verdict":"정답","why":"i = 1, 2, 3일 때 22 + 44 + 55 = 121이 출력된다."},{"verdict":"오답","why":"132는 네 원소 모두(11 + 22 + 44 + 55) 더한 값이다. i = 0은 반복에 포함되지 않으므로 틀리다."}],"keywords":[{"term":"2차원 배열의 메모리 배치","desc":"행 우선으로 연속 저장, a[0][0], a[0][1], a[1][0], a[1][1] 순"},{"term":"포인터 산술","desc":"*(p + i)는 p가 가리키는 곳에서 i번째 뒤 원소의 값"},{"term":"a[0]","desc":"0행의 시작 주소, &a[0][0]과 같음"}],"memo":"반복 시작값을 꼭 확인한다. i = 1부터면 첫 원소(11)는 빠진다."}},{"id":"written-2021-2-74","no":74,"unit":"프로그래밍 언어 활용","q":"페이징 기법에서 페이지 크기가 작아질수록 발생하는 현상이 아닌 것은?","choices":["기억장소 이용 효율이 증가한다.","입·출력 시간이 늘어난다.","내부 단편화가 감소한다.","페이지 맵 테이블의 크기가 감소한다."],"ans":4,"rate":50,"exp":{"concept":"페이징 기법에서 페이지 크기가 작아지면 같은 프로그램이 더 많은 페이지로 나뉜다. 필요한 부분만 정밀하게 올릴 수 있어 내부 단편화가 줄고 기억장소 이용 효율이 높아지지만, 페이지 수가 많아져 페이지 맵 테이블이 커지고 입출력 횟수와 시간이 늘어난다.","choices":[{"verdict":"오답","why":"페이지가 작으면 필요한 부분만 올릴 수 있어 기억장소 이용 효율이 증가한다."},{"verdict":"오답","why":"페이지가 작으면 옮겨야 할 페이지 수가 많아져 입출력 시간이 늘어난다."},{"verdict":"오답","why":"페이지가 작으면 마지막 페이지에서 남는 공간이 작아지므로 내부 단편화가 감소한다."},{"verdict":"정답","why":"페이지가 작으면 페이지 수가 많아지므로 페이지 맵 테이블의 크기는 증가한다. 감소한다는 설명은 틀리다."}],"keywords":[{"term":"페이지 크기가 작을 때","desc":"단편화 감소, 효율 증가, 페이지 테이블 증가, 입출력 시간 증가"},{"term":"페이지 크기가 클 때","desc":"페이지 테이블 감소, 입출력 효율 증가, 내부 단편화 증가"},{"term":"내부 단편화","desc":"할당된 공간 안에서 쓰이지 않고 남는 부분"}],"memo":"페이지가 작으면 '개수'가 늘어난다. 개수에 비례하는 것(페이지 테이블, 입출력 횟수)은 커진다."}},{"id":"written-2021-2-75","no":75,"unit":"프로그래밍 언어 활용","q":"다음 중 가장 강한 응집도(Cohesion)는?","choices":["Sequential Cohesion","Procedural Cohesion","Logical Cohesion","Coincidental Cohesion"],"ans":1,"rate":56,"wiki":[{"title":"응집도","url":"https://itwiki.kr/w/응집도"}],"exp":{"concept":"응집도(Cohesion)는 한 모듈 안의 요소들이 얼마나 하나의 목적으로 뭉쳐 있는지를 나타내며, 강할수록 좋다. 강한 것부터 기능적 > 순차적 > 교환적(통신적) > 절차적 > 시간적 > 논리적 > 우연적 응집도 순서다. 보기 중 가장 강한 것은 순차적 응집도다.","choices":[{"verdict":"정답","why":"순차적 응집도(Sequential Cohesion)는 한 활동의 출력이 다음 활동의 입력으로 쓰이는 응집도로, 보기 중 가장 강하다."},{"verdict":"오답","why":"절차적 응집도(Procedural Cohesion)는 여러 기능을 정해진 순서대로 수행하는 응집도로, 순차적보다 약하다."},{"verdict":"오답","why":"논리적 응집도(Logical Cohesion)는 논리적으로 비슷한 기능들을 한 모듈에 모아 둔 응집도로, 절차적보다 약하다."},{"verdict":"오답","why":"우연적 응집도(Coincidental Cohesion)는 서로 관련 없는 요소들이 모인 응집도로, 가장 약하다."}],"keywords":[{"term":"기능적 응집도","desc":"모듈 내 모든 요소가 단일 기능을 위해 수행, 가장 강함"},{"term":"순차적 응집도","desc":"한 활동의 출력이 다음 활동의 입력으로 사용"},{"term":"교환적(통신적) 응집도","desc":"같은 입출력 자료를 사용하는 활동들이 모임"},{"term":"우연적 응집도","desc":"서로 관련 없는 요소들이 모임, 가장 약함"}],"memo":"응집도 강→약은 '기순교절시논우'(기능·순차·교환·절차·시간·논리·우연)."}},{"id":"written-2021-2-76","no":76,"unit":"프로그래밍 언어 활용","q":"TCP 프로토콜과 관련한 설명으로 틀린 것은?","choices":["인접한 노드 사이의 프레임 전송 및 오류를 제어한다.","흐름 제어(Flow Control)의 기능을 수행한다.","전이 중(Full Duplex) 방식의 양방향 가상회선을 제공한다.","전송 데이터와 응답 데이터를 함께 전송할 수 있다."],"ans":1,"rate":46,"wiki":[{"title":"TCP","url":"https://itwiki.kr/w/TCP"},{"title":"흐름 제어","url":"https://itwiki.kr/w/흐름 제어"},{"title":"데이터 전송","url":"https://itwiki.kr/w/데이터 전송"},{"title":"전이중 통신","url":"https://itwiki.kr/w/전이중 통신"}],"exp":{"concept":"TCP는 전송 계층(4계층) 프로토콜로, 연결을 맺은 뒤 신뢰성 있게 데이터를 전달한다. 흐름 제어, 오류 제어, 혼잡 제어를 하고 전이중(Full Duplex) 양방향 가상 회선을 제공한다. 인접한 노드 사이에서 프레임을 전송하고 오류를 제어하는 것은 데이터 링크 계층(2계층)의 역할이다.","choices":[{"verdict":"정답","why":"인접 노드 사이의 프레임 전송과 오류 제어는 데이터 링크 계층의 기능이다. TCP는 종단 간(End-to-End) 세그먼트 전송을 담당한다."},{"verdict":"오답","why":"TCP는 슬라이딩 윈도우 방식으로 흐름 제어를 수행한다."},{"verdict":"오답","why":"TCP는 전이중 방식의 양방향 가상 회선을 제공한다."},{"verdict":"오답","why":"TCP는 보낼 데이터에 받은 데이터에 대한 응답(ACK)을 함께 실어 보내는 피기배킹(Piggybacking)을 할 수 있다."}],"keywords":[{"term":"TCP","desc":"연결형·신뢰성 전송 계층 프로토콜, 흐름·오류·혼잡 제어"},{"term":"UDP","desc":"비연결형·비신뢰성 전송 계층 프로토콜, 빠름"},{"term":"피기배킹(Piggybacking)","desc":"데이터 전송 시 응답(ACK)을 함께 실어 보내는 기법"},{"term":"데이터 링크 계층","desc":"인접 노드 간 프레임 전송, 흐름·오류 제어"}],"memo":"'프레임'과 '인접 노드'는 2계층 단어다. TCP(4계층)는 '세그먼트'와 '종단 간'."}},{"id":"written-2021-2-77","no":77,"unit":"프로그래밍 언어 활용","q":"C언어에서 연산자 우선순위가 높은 것에서 낮은 것으로 바르게 나열된 것은?\n<img src=\"data/img/eip_written_20210515_077.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["㉠, ㉥, ㉣, ㉢, ㉡, ㉤","㉠, ㉣, ㉥, ㉢, ㉡, ㉤","㉠, ㉣, ㉥, ㉢, ㉤, ㉡","㉠, ㉥, ㉣, ㉤, ㉡, ㉢"],"ans":1,"rate":54,"exp":{"concept":"C 연산자는 우선순위가 높은 순서로 괄호 등 최우선 연산자 → 단항 → 산술(*, /, % 다음 +, -) → 시프트(<<, >>) → 관계(<, >, <=, >=) → 같음(==, !=) → 비트 → 논리(&&, ||) → 조건 → 대입 → 콤마다. 따라서 ( ) → / → << → < → == → || 순서다.","choices":[{"verdict":"정답","why":"㉠( ), ㉥ /, ㉣ <<, ㉢ <, ㉡ ==, ㉤ || 순서로 우선순위가 높은 것부터 바르게 나열했다."},{"verdict":"오답","why":"시프트(<<)가 산술 연산자(/)보다 앞에 있어 틀리다. 산술 연산자가 시프트보다 우선순위가 높다."},{"verdict":"오답","why":"시프트(<<)가 산술(/)보다 앞이고, 논리 OR(||)이 같음(==)보다 앞이라 틀리다."},{"verdict":"오답","why":"논리 OR(||)이 같음(==)과 관계(<)보다 앞에 있어 틀리다. ||는 이들 중 우선순위가 가장 낮다."}],"keywords":[{"term":"연산자 우선순위","desc":"단항 > 산술 > 시프트 > 관계(<, > 다음 ==, !=) > 비트 > 논리 > 조건 > 대입 > 콤마"},{"term":"시프트 연산자(<<, >>)","desc":"비트를 왼쪽·오른쪽으로 이동, 산술보다 낮고 관계보다 높음"},{"term":"관계·같음 연산자","desc":"<, >, <=, >=가 ==, !=보다 우선순위가 높음"}],"memo":"'단산시관비논조대콤'(단항·산술·시프트·관계·비트·논리·조건·대입·콤마) 순서로 외운다. 관계 연산자 안에서는 <, >가 ==, !=보다 먼저다."}},{"id":"written-2021-2-78","no":78,"unit":"프로그래밍 언어 활용","q":"C언어 라이브러리 중 stdlib.h에 대한설명으로 옳은 것은?","choices":["문자열을 수치 데이터로 바꾸는 문자 변환함수와 수치를 문자열로 바꿔주는 변환함수 등이 있다.","문자열 처리 함수로 strlen()이 포함되어 있다.","표준 입출력 라이브러리이다.","삼각 함수, 제곱근, 지수 등 수학적인 함수를 내장하고 있다."],"ans":1,"rate":54,"exp":{"concept":"C 표준 라이브러리는 헤더 파일별로 역할이 나뉜다. stdio.h는 표준 입출력(printf, scanf), string.h는 문자열 처리(strlen, strcpy), math.h는 수학 함수(sin, sqrt, pow), stdlib.h는 자료형 변환(atoi, atof), 난수(rand), 메모리 할당(malloc, free) 등 일반 유틸리티 함수를 담고 있다.","choices":[{"verdict":"정답","why":"stdlib.h에는 문자열을 수치로 바꾸는 atoi, atof 같은 자료형 변환 함수가 있으므로 맞는 설명이다."},{"verdict":"오답","why":"strlen()은 string.h에 들어 있는 문자열 처리 함수다."},{"verdict":"오답","why":"표준 입출력 라이브러리는 stdio.h다."},{"verdict":"오답","why":"삼각 함수, 제곱근, 지수 등 수학 함수는 math.h에 들어 있다."}],"keywords":[{"term":"stdlib.h","desc":"자료형 변환(atoi, atof), 난수(rand), 메모리 할당(malloc, free) 등"},{"term":"stdio.h","desc":"표준 입출력(printf, scanf, fopen)"},{"term":"string.h","desc":"문자열 처리(strlen, strcpy, strcmp)"},{"term":"math.h","desc":"수학 함수(sin, sqrt, pow)"}],"memo":"std'lib'는 잡다한 유틸(변환·난수·메모리), std'io'는 입출력, 'string'은 문자열, 'math'는 수학."}},{"id":"written-2021-2-79","no":79,"unit":"프로그래밍 언어 활용","q":"자바스크립트(JavaScript)와 관련한 설명으로 틀린 것은? (문제 오류로 가답안 발표시 2번으로 발표되었지만 확정 답안 발표시 모두 정답처리 되었습니다. 여기서는 가답안인 2번을 누르면 정답 처리 됩니다.)","choices":["프로토타입(Prototype)의 개념이 존재한다.","클래스 기반으로 객체 상속을 지원한다.","Prototype Link와 Prototype Object를 활용할 수 있다.","객체지향 언어이다."],"ans":2,"rate":80,"exp":{"concept":"자바스크립트는 클래스가 아니라 프로토타입(Prototype)을 기반으로 객체를 만들고 상속하는 객체지향 스크립트 언어다. 모든 객체는 자신의 원형인 프로토타입 객체(Prototype Object)와 연결(Prototype Link)되어 속성을 물려받는다. ES6부터 class 문법이 생겼지만 내부 동작은 여전히 프로토타입 기반이다.","choices":[{"verdict":"오답","why":"자바스크립트에는 프로토타입 개념이 존재하므로 맞는 설명이다."},{"verdict":"정답","why":"자바스크립트는 클래스가 아니라 프로토타입을 기반으로 객체 상속을 지원하므로 이 문항에서 틀린 설명으로 본다."},{"verdict":"오답","why":"자바스크립트는 Prototype Link와 Prototype Object를 이용해 상속을 구현하므로 맞는 설명이다."},{"verdict":"오답","why":"자바스크립트는 프로토타입 기반의 객체지향 언어이므로 맞는 설명이다."}],"keywords":[{"term":"프로토타입 기반 상속","desc":"객체가 다른 객체(프로토타입)를 원형으로 삼아 속성을 물려받는 방식"},{"term":"Prototype Object","desc":"함수 정의 시 함께 만들어지는 원형 객체"},{"term":"Prototype Link","desc":"객체가 자신의 원형 객체를 가리키는 연결(__proto__)"}],"memo":"자바스크립트 상속 키워드는 '클래스'가 아니라 '프로토타입'.","doubt":"ES6부터 자바스크립트에도 class와 extends 문법이 생겨 클래스 형태로 상속을 쓸 수 있으므로, 보기 내용상 2번도 맞는 설명으로 볼 수 있다. 그러면 1, 3, 4번도 모두 맞는 설명이라 틀린 보기가 없게 된다. 문제에 붙은 안내에 따르면 확정 답안에서 모든 보기가 정답 처리되었고, 이 앱은 가답안인 2번으로 채점한다."}},{"id":"written-2021-2-80","no":80,"unit":"프로그래밍 언어 활용","q":"OSI 7계층 중 네트워크 계층에 대한 설명으로 틀린 것은?","choices":["패킷을 발신지로부터 최종 목적지까지 전달하는 책임을 진다.","한 노드로부터 다른 노드로 프레임을 전송하는 책임을 진다.","패킷에 발신지와 목적지의 논리 주소를 추가한다.","라우터 또는 교환기는 패킷 전달을 위해 경로를 지정하거나 교환 기능을 제공한다."],"ans":2,"rate":54,"wiki":[{"title":"OSI 7계층","url":"https://itwiki.kr/w/OSI 7계층"}],"exp":{"concept":"OSI 7계층에서 네트워크 계층(3계층)은 패킷을 출발지에서 최종 목적지까지 전달하는 책임을 진다. 논리 주소(IP 주소)를 붙이고, 라우터가 경로를 정해(라우팅) 패킷을 전달한다. 바로 옆 노드로 프레임을 전달하는 것은 데이터 링크 계층(2계층)이다.","choices":[{"verdict":"오답","why":"패킷을 발신지에서 최종 목적지까지 전달하는 것은 네트워크 계층의 역할이다."},{"verdict":"정답","why":"한 노드에서 인접한 다른 노드로 프레임을 전송하는 것은 데이터 링크 계층의 역할이다."},{"verdict":"오답","why":"패킷에 발신지와 목적지의 논리 주소(IP 주소)를 추가하는 것은 네트워크 계층의 역할이다."},{"verdict":"오답","why":"라우터나 교환기가 경로를 지정하고 교환 기능을 제공하는 것은 네트워크 계층의 역할이다."}],"keywords":[{"term":"네트워크 계층(3계층)","desc":"논리 주소(IP), 라우팅, 패킷 전달, 장비는 라우터"},{"term":"데이터 링크 계층(2계층)","desc":"인접 노드 간 프레임 전송, 물리 주소(MAC), 장비는 스위치·브리지"},{"term":"전송 계층(4계층)","desc":"종단 간 신뢰성 전송, TCP·UDP"}],"memo":"계층별 전송 단위: 2계층 프레임, 3계층 패킷, 4계층 세그먼트."}},{"id":"written-2021-2-81","no":81,"unit":"정보시스템 구축 관리","q":"다음 내용이 설명하는 것은?\n<img src=\"data/img/eip_written_20210515_081.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["SAN","MBR","NAC","NIC"],"ans":1,"rate":58,"wiki":[{"title":"SAN","url":"https://itwiki.kr/w/SAN"},{"title":"NAC","url":"https://itwiki.kr/w/NAC"},{"title":"NIC","url":"https://itwiki.kr/w/NIC"},{"title":"MBR","url":"https://itwiki.kr/w/MBR"}],"exp":{"concept":"SAN(Storage Area Network)은 여러 서버와 저장장치를 광채널(Fibre Channel) 스위치로 연결한 저장장치 전용 네트워크다. 서로 다른 운영체제의 서버들도 같은 저장장치를 공유할 수 있고, 여러 저장장치와 백업 장비를 하나처럼 관리한다.","choices":[{"verdict":"정답","why":"광채널 스위치로 고속 전송·장거리 연결·멀티 프로토콜을 지원하고, 여러 기종이 저장장치를 공유하도록 단일화한 시스템은 SAN이다."},{"verdict":"오답","why":"MBR(Master Boot Record)은 디스크의 첫 섹터에 있는 부팅 정보와 파티션 정보다."},{"verdict":"오답","why":"NAC(Network Access Control)는 네트워크에 접속하는 단말의 보안 상태를 검사해 접근을 통제하는 솔루션이다."},{"verdict":"오답","why":"NIC(Network Interface Card)는 컴퓨터를 네트워크에 연결하는 랜카드다."}],"keywords":[{"term":"SAN(Storage Area Network)","desc":"광채널 스위치로 서버와 저장장치를 연결한 전용 네트워크"},{"term":"NAS(Network Attached Storage)","desc":"일반 네트워크(LAN)에 직접 연결하는 파일 공유 저장장치"},{"term":"DAS(Direct Attached Storage)","desc":"서버에 저장장치를 직접 연결하는 방식"}],"memo":"'광채널 스위치', '저장장치 공유'가 보이면 SAN. 저장 방식 3종 DAS·NAS·SAN을 함께 외운다."}},{"id":"written-2021-2-82","no":82,"unit":"정보시스템 구축 관리","q":"SSH(Secure Shell)에 대한 설명으로 틀린 것은?","choices":["SSH의 기본 네트워크 포트는 220번을 사용한다","전송되는 데이터는 암호화 된다.","키를 통한 인증은 클라이언트의 공개키를 서버에 등록해야 한다.","서로 연결되어 있는 컴퓨터 간 원격 명령실행이나 셀 서비스 등을 수행한다."],"ans":1,"rate":65,"wiki":[{"title":"SSH","url":"https://itwiki.kr/w/SSH"}],"exp":{"concept":"SSH(Secure Shell)는 네트워크로 다른 컴퓨터에 접속해 명령을 실행하거나 파일을 옮길 때 통신 내용을 암호화하는 프로토콜이다. 기본 포트는 22번이며, 비밀번호 대신 키로 인증할 때는 클라이언트의 공개키를 서버에 등록해 둔다.","choices":[{"verdict":"정답","why":"SSH의 기본 포트는 22번이다. 220번이라는 설명은 틀리다."},{"verdict":"오답","why":"SSH는 전송되는 데이터를 암호화하므로 맞는 설명이다."},{"verdict":"오답","why":"키 인증 방식은 클라이언트의 공개키를 서버에 등록하고, 클라이언트가 가진 개인키로 인증하므로 맞는 설명이다."},{"verdict":"오답","why":"SSH는 연결된 컴퓨터 사이에서 원격 명령 실행이나 셸 서비스 등을 제공하므로 맞는 설명이다."}],"keywords":[{"term":"SSH","desc":"암호화된 원격 접속 프로토콜, 기본 포트 22"},{"term":"Telnet","desc":"암호화하지 않는 원격 접속 프로토콜, 기본 포트 23"},{"term":"FTP","desc":"파일 전송 프로토콜, 기본 포트 20(데이터)·21(제어)"}],"memo":"포트 번호 차례로 FTP 20·21, SSH 22, Telnet 23, SMTP 25."}},{"id":"written-2021-2-83","no":83,"unit":"정보시스템 구축 관리","q":"CBD(Component Based Development) SW개발 표준 산출물 중 분석 단계에 해당하는 것은?","choices":["클래스 설계서","통합시험 결과서","프로그램 코드","사용자 요구사항 정의서"],"ans":4,"rate":63,"exp":{"concept":"CBD(컴포넌트 기반 개발) 방법론은 분석, 설계, 구현, 시험 단계마다 표준 산출물이 있다. 분석 단계에서는 사용자 요구사항 정의서, 유스케이스 명세서, 요구사항 추적표 등을 만든다.","choices":[{"verdict":"오답","why":"클래스 설계서는 설계 단계 산출물이다."},{"verdict":"오답","why":"통합시험 결과서는 시험 단계 산출물이다."},{"verdict":"오답","why":"프로그램 코드는 구현 단계 산출물이다."},{"verdict":"정답","why":"사용자 요구사항 정의서는 사용자의 요구를 정리하는 분석 단계 산출물이다."}],"keywords":[{"term":"CBD(Component Based Development)","desc":"재사용 가능한 컴포넌트를 조합해 개발하는 방법론"},{"term":"분석 단계 산출물","desc":"사용자 요구사항 정의서, 유스케이스 명세서, 요구사항 추적표"},{"term":"설계 단계 산출물","desc":"클래스 설계서, 사용자 인터페이스 설계서, 아키텍처 설계서 등"}],"memo":"'요구사항'이 들어간 산출물은 분석, '설계서'는 설계, '코드'는 구현, '시험'은 시험 단계."}},{"id":"written-2021-2-84","no":84,"unit":"정보시스템 구축 관리","q":"다음 내용이 설명하는 접근 제어 모델은?\n<img src=\"data/img/eip_written_20210515_084.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["Clark-Wilson Integrity Model","PDCA Model","Bell-Lapadula Model","Chinese Wall Model"],"ans":3,"rate":61,"wiki":[{"title":"접근제어","url":"https://itwiki.kr/w/접근제어"}],"exp":{"concept":"벨-라파둘라(Bell-LaPadula) 모델은 군대처럼 보안 등급이 나뉜 환경에서 정보의 기밀성을 지키기 위한 접근 제어 모델이다. 자기보다 높은 등급의 문서는 읽을 수 없고(No Read Up), 자기보다 낮은 등급의 문서에는 쓸 수 없다(No Write Down). 비밀이 아래로 새지 않게 하는 것이 목적이다.","choices":[{"verdict":"오답","why":"클락-윌슨(Clark-Wilson) 무결성 모델은 데이터의 무결성을 지키기 위해 허가된 프로그램을 통해서만 데이터를 변경하게 하는 모델이다."},{"verdict":"오답","why":"PDCA 모델은 계획(Plan)-실행(Do)-점검(Check)-조치(Act)를 반복하는 관리 개선 사이클로, 접근 제어 모델이 아니다."},{"verdict":"정답","why":"보안 등급에 따라 높은 등급 읽기와 낮은 등급 쓰기를 제한해 기밀성을 보호하는 것은 벨-라파둘라 모델이다."},{"verdict":"오답","why":"만리장성(Chinese Wall) 모델은 이해 충돌이 있는 정보에 접근하지 못하게 막는 모델이다."}],"keywords":[{"term":"벨-라파둘라(BLP) 모델","desc":"기밀성 모델, No Read Up, No Write Down"},{"term":"비바(Biba) 모델","desc":"무결성 모델, No Read Down, No Write Up"},{"term":"클락-윌슨 모델","desc":"무결성 모델, 허가된 프로그램을 통한 변경만 허용"},{"term":"만리장성(Chinese Wall) 모델","desc":"이해 충돌 방지 모델"}],"memo":"BLP는 기밀성이라 '위로 읽기, 아래로 쓰기' 금지. 비바는 무결성이라 정반대."}},{"id":"written-2021-2-85","no":85,"unit":"정보시스템 구축 관리","q":"하둡(Hadoop)과 관계형 데이터베이스간에 데이터를 전송할 수 있도록 설계된 도구는?","choices":["Apnic","Topology","Sqoop","SDB."],"ans":3,"rate":75,"wiki":[{"title":"하둡","url":"https://itwiki.kr/w/하둡"}],"exp":{"concept":"스쿱(Sqoop)은 하둡(Hadoop)과 관계형 데이터베이스 사이에서 대량의 데이터를 가져오고 내보내는 도구다. 관계형 DB의 테이블을 하둡 파일 시스템으로 옮기거나 그 반대로 옮길 때 쓴다. 이름도 SQL과 Hadoop을 합친 것이다.","choices":[{"verdict":"오답","why":"APNIC은 아시아·태평양 지역의 IP 주소를 할당·관리하는 인터넷 주소 관리 기관이다."},{"verdict":"오답","why":"토폴로지(Topology)는 네트워크를 이루는 노드와 회선의 연결 형태(성형, 버스형, 링형 등)다."},{"verdict":"정답","why":"스쿱(Sqoop)은 하둡과 관계형 데이터베이스 사이의 데이터 전송을 위한 도구다."},{"verdict":"오답","why":"SDB는 하둡과 관계형 DB 간 데이터 전송 도구로 출제 범위에서 쓰이는 표준 용어가 아니다."}],"keywords":[{"term":"스쿱(Sqoop)","desc":"하둡과 관계형 DB 사이의 데이터 전송 도구"},{"term":"하둡(Hadoop)","desc":"오픈 소스 기반 대용량 데이터 분산 저장·처리 프레임워크"},{"term":"맵리듀스(MapReduce)","desc":"대용량 데이터를 분산 병렬 처리하는 하둡의 프로그래밍 모델"}],"memo":"Sqoop = SQL + Hadoop. 이름에 두 세계가 다 들어 있다."}},{"id":"written-2021-2-86","no":86,"unit":"정보시스템 구축 관리","q":"라우팅 프로토콜인 OSPF(Open Shortest Path First)에 대한 설명으로 옳지 않은 것은?","choices":["네트워크 변화에 신속하게 대처할 수 있다.","거리 벡터 라우팅 프로토콜이라고 한다.","멀티캐스팅을 지원한다.","최단 경로 탐색에 Dijkstra 알고리즘을 사용한다."],"ans":2,"rate":50,"wiki":[{"title":"OSPF","url":"https://itwiki.kr/w/OSPF"},{"title":"RIP","url":"https://itwiki.kr/w/RIP"}],"exp":{"concept":"라우팅 프로토콜은 거리 벡터 방식(RIP 등)과 링크 상태 방식(OSPF 등)으로 나뉜다. OSPF는 링크 상태 라우팅 프로토콜로, 전체 네트워크 지도를 바탕으로 다익스트라(Dijkstra) 알고리즘으로 최단 경로를 계산한다. 네트워크 변화가 생기면 빠르게 반영하고, 멀티캐스트로 라우팅 정보를 주고받는다.","choices":[{"verdict":"오답","why":"OSPF는 변화가 있을 때 링크 상태 정보를 즉시 알려 네트워크 변화에 빠르게 대처한다."},{"verdict":"정답","why":"OSPF는 거리 벡터가 아니라 링크 상태(Link State) 라우팅 프로토콜이다. 거리 벡터 방식의 대표는 RIP다."},{"verdict":"오답","why":"OSPF는 멀티캐스트 주소로 라우팅 정보를 교환하므로 멀티캐스팅을 지원한다."},{"verdict":"오답","why":"OSPF는 다익스트라 알고리즘으로 최단 경로를 탐색한다."}],"keywords":[{"term":"OSPF","desc":"링크 상태 라우팅 프로토콜, 다익스트라 알고리즘 사용, 대규모 네트워크에 적합"},{"term":"RIP","desc":"거리 벡터 라우팅 프로토콜, 벨만-포드 알고리즘, 최대 홉 수 15"},{"term":"BGP","desc":"서로 다른 자율 시스템(AS) 사이의 라우팅 프로토콜"}],"memo":"RIP는 거리 벡터(벨만-포드), OSPF는 링크 상태(다익스트라). 짝으로 외운다."}},{"id":"written-2021-2-87","no":87,"unit":"정보시스템 구축 관리","q":"소프트웨어 비용 추정 모형(estimation models)이 아닌 것은?","choices":["COCOMO","Putnam","Function-Point","PERT"],"ans":4,"rate":62,"exp":{"concept":"소프트웨어 비용 추정 모형에는 프로그램 규모(코드 라인 수)를 바탕으로 하는 COCOMO, 생명주기 전체의 노력 분포를 가정하는 Putnam, 기능의 수와 복잡도를 점수로 매기는 기능 점수(FP) 모형 등이 있다. PERT는 비용 추정이 아니라 프로젝트 일정을 계획하는 기법이다.","choices":[{"verdict":"오답","why":"COCOMO는 원시 코드 라인 수를 바탕으로 비용을 추정하는 모형이다."},{"verdict":"오답","why":"Putnam 모형은 생명주기 전 과정에 걸친 노력 분포를 가정해 비용을 추정하는 모형이다."},{"verdict":"오답","why":"기능 점수(Function Point) 모형은 기능별 가중치로 점수를 계산해 비용을 추정하는 모형이다."},{"verdict":"정답","why":"PERT(Program Evaluation and Review Technique)는 작업의 일정과 순서를 네트워크로 표현해 일정을 계획하는 기법으로, 비용 추정 모형이 아니다."}],"keywords":[{"term":"COCOMO","desc":"LOC 기반 비용 추정, 조직형·반분리형·내장형"},{"term":"Putnam 모형","desc":"Rayleigh-Norden 곡선 기반 생명주기 노력 분포 추정"},{"term":"기능 점수(FP)","desc":"기능 수와 복잡도에 가중치를 주어 규모·비용 추정"},{"term":"PERT","desc":"낙관·보통·비관 시간으로 일정을 추정하는 일정 계획 기법"}],"memo":"PERT, CPM, 간트 차트는 '일정' 관리 도구다. 비용 추정 목록에 섞여 나오면 그것이 답이다."}},{"id":"written-2021-2-88","no":88,"unit":"정보시스템 구축 관리","q":"코드의 기입 과정에서 원래 '12536‘으로 기입되어야 하는데 ’12936‘으로 표기되었을 경우, 어떤 코드 오류에 해당하는가?","choices":["Addition Error","Omission Error","Sequence Error","Transcription Error"],"ans":4,"rate":57,"wiki":[{"title":"코드","url":"https://itwiki.kr/w/코드"}],"exp":{"concept":"코드 오류의 종류에는 사본 오류, 전위 오류, 이중 오류, 생략 오류, 추가 오류, 임의 오류가 있다. 12536이 12936으로 바뀐 것처럼 한 자리를 잘못 옮겨 적은 것은 사본 오류(필사 오류, Transcription Error)다.","choices":[{"verdict":"오답","why":"추가 오류(Addition Error)는 입력할 때 한 자리를 더 적은 오류다(예: 12536 → 125367)."},{"verdict":"오답","why":"생략 오류(Omission Error)는 한 자리를 빠뜨린 오류다(예: 12536 → 1256)."},{"verdict":"오답","why":"Sequence Error는 표준 코드 오류 분류에 쓰이는 이름이 아니다. 자리 순서가 서로 바뀌는 오류는 전위 오류(Transposition Error)라고 한다."},{"verdict":"정답","why":"한 자리(5)를 다른 숫자(9)로 잘못 기록한 것은 사본 오류(Transcription Error)다."}],"keywords":[{"term":"사본 오류(Transcription Error)","desc":"한 자리를 잘못 기록한 오류, 필사 오류라고도 함"},{"term":"전위 오류(Transposition Error)","desc":"인접한 두 자리가 서로 바뀐 오류(12536 → 12356)"},{"term":"이중 오류(Double Transposition Error)","desc":"전위 오류가 두 군데 이상 생긴 오류"},{"term":"생략·추가 오류","desc":"한 자리를 빠뜨리거나 더 적은 오류"}],"memo":"글자가 '바뀌면' 사본, 자리가 '뒤집히면' 전위, '빠지면' 생략, '늘면' 추가."}},{"id":"written-2021-2-89","no":89,"unit":"정보시스템 구축 관리","q":"ISO 12207 표준의 기본 생명주기의 주요 프로세스에 해당하지 않는 것은?","choices":["획득 프로세스","개발 프로세스","성능평가 프로세스","유지보수 프로세스"],"ans":3,"rate":46,"exp":{"concept":"ISO/IEC 12207은 소프트웨어 생명주기 프로세스의 국제 표준으로, 기본 생명주기 프로세스, 지원 생명주기 프로세스, 조직 생명주기 프로세스로 나뉜다. 기본 생명주기 프로세스는 획득, 공급, 개발, 운영, 유지보수 프로세스다.","choices":[{"verdict":"오답","why":"획득 프로세스는 기본 생명주기 프로세스에 해당한다."},{"verdict":"오답","why":"개발 프로세스는 기본 생명주기 프로세스에 해당한다."},{"verdict":"정답","why":"성능평가 프로세스는 ISO 12207의 기본 생명주기 프로세스에 없다."},{"verdict":"오답","why":"유지보수 프로세스는 기본 생명주기 프로세스에 해당한다."}],"keywords":[{"term":"기본 생명주기 프로세스","desc":"획득, 공급, 개발, 운영, 유지보수"},{"term":"지원 생명주기 프로세스","desc":"문서화, 형상 관리, 품질 보증, 검증, 확인, 합동 검토, 감사, 문제 해결"},{"term":"조직 생명주기 프로세스","desc":"관리, 기반 구조, 개선, 교육 훈련"}],"memo":"기본 프로세스는 '획공개운유'(획득·공급·개발·운영·유지보수). 사고(획득)·팔고(공급)·만들고·쓰고·고친다."}},{"id":"written-2021-2-90","no":90,"unit":"정보시스템 구축 관리","q":"소프트웨어 비용 산정 기법 중 개발 유형으로 organic, semi-detached, embedded로 구분되는 것은?","choices":["PUTNAM","COCOMO","FP","SLIM"],"ans":2,"rate":85,"wiki":[{"title":"COCOMO","url":"https://itwiki.kr/w/COCOMO"}],"exp":{"concept":"COCOMO는 보헴(Boehm)이 제안한 비용 산정 모형으로, 원시 코드 라인 수(LOC)로 비용을 추정한다. 소프트웨어 개발 유형을 규모와 복잡도에 따라 조직형(Organic), 반분리형(Semi-detached), 내장형(Embedded)으로 나눈다.","choices":[{"verdict":"오답","why":"PUTNAM 모형은 생명주기 전 과정의 노력 분포를 가정하는 비용 산정 모형으로, organic 같은 개발 유형 구분이 없다."},{"verdict":"정답","why":"COCOMO는 개발 유형을 조직형(organic), 반분리형(semi-detached), 내장형(embedded)으로 구분한다."},{"verdict":"오답","why":"FP(기능 점수) 모형은 기능 점수로 비용을 산정하는 모형으로, 이런 개발 유형 구분이 없다."},{"verdict":"오답","why":"SLIM은 Putnam 모형을 바탕으로 한 자동화 비용 추정 도구다."}],"keywords":[{"term":"조직형(Organic)","desc":"5만 라인 이하의 중소 규모 사무 처리용 소프트웨어"},{"term":"반분리형(Semi-detached)","desc":"30만 라인 이하의 운영체제, DBMS 등"},{"term":"내장형(Embedded)","desc":"30만 라인 이상의 최대형 규모, 신호기 제어 시스템 등"},{"term":"COCOMO 모형 종류","desc":"기본형(Basic), 중간형(Intermediate), 발전형(Detailed)"}],"memo":"organic·semi-detached·embedded가 나오면 무조건 COCOMO."}},{"id":"written-2021-2-91","no":91,"unit":"정보시스템 구축 관리","q":"SPICE 모델의 프로세스 수행능력 수준의 단계별 설명이 틀린 것은?","choices":["수준 7 - 미완성 단계","수준 5 - 최적화 단계","수준 4 - 예측 단계","수준 3 - 확립 단계"],"ans":1,"rate":74,"wiki":[{"title":"SPICE","url":"https://itwiki.kr/w/SPICE"}],"exp":{"concept":"SPICE(ISO/IEC 15504)는 소프트웨어 프로세스의 수행 능력을 평가하는 국제 표준이다. 수행 능력 수준은 0부터 5까지 6단계로, 0 불완전, 1 수행, 2 관리, 3 확립, 4 예측, 5 최적화 단계다.","choices":[{"verdict":"정답","why":"SPICE의 수준은 0~5까지만 있으므로 수준 7은 존재하지 않는다. 미완성(불완전) 단계는 수준 0이다."},{"verdict":"오답","why":"수준 5는 최적화(Optimizing) 단계다."},{"verdict":"오답","why":"수준 4는 예측(Predictable) 단계다."},{"verdict":"오답","why":"수준 3은 확립(Established) 단계다."}],"keywords":[{"term":"SPICE","desc":"ISO/IEC 15504, 소프트웨어 프로세스 평가·개선 국제 표준"},{"term":"SPICE 수준","desc":"0 불완전, 1 수행, 2 관리, 3 확립, 4 예측, 5 최적화"},{"term":"CMMI","desc":"1 초기, 2 관리, 3 정의, 4 정량적 관리, 5 최적화"}],"memo":"SPICE는 0부터 시작해 5까지(6단계). 7이 나오면 바로 틀린 보기다."}},{"id":"written-2021-2-92","no":92,"unit":"정보시스템 구축 관리","q":"PC, TV, 휴대폰에서 원하는 콘텐츠를 끊김없이 자유롭게 이용할 수 있는 서비스는?","choices":["Memristor","MEMS","SNMP","N-Screen"],"ans":4,"rate":66,"exp":{"concept":"N 스크린(N-Screen)은 하나의 콘텐츠를 PC, TV, 휴대폰 등 여러(N개) 기기에서 끊김 없이 이어서 이용할 수 있게 하는 서비스다. 휴대폰으로 보던 드라마를 집에 와서 TV로 이어 보는 것이 예다.","choices":[{"verdict":"오답","why":"멤리스터(Memristor)는 메모리(Memory)와 저항(Resistor)을 합친 말로, 전원이 꺼져도 이전 상태를 기억하는 전기 소자다."},{"verdict":"오답","why":"MEMS(Micro Electro Mechanical Systems)는 초정밀 반도체 기술로 기계 부품, 센서 등을 미세하게 만드는 기술이다."},{"verdict":"오답","why":"SNMP(Simple Network Management Protocol)는 네트워크 장비를 감시·관리하는 프로토콜이다."},{"verdict":"정답","why":"PC, TV, 휴대폰에서 콘텐츠를 끊김 없이 이용하게 하는 서비스는 N 스크린이다."}],"keywords":[{"term":"N 스크린(N-Screen)","desc":"여러 기기에서 하나의 콘텐츠를 끊김 없이 이용하는 서비스"},{"term":"멤리스터(Memristor)","desc":"이전 상태를 기억하는 저항 소자"},{"term":"SNMP","desc":"네트워크 관리 프로토콜"}],"memo":"스크린(화면)이 N개, 즉 여러 기기 화면에서 이어 보기."}},{"id":"written-2021-2-93","no":93,"unit":"정보시스템 구축 관리","q":"해쉬(Hash) 기법에 대한 설명으로 틀린 것은?","choices":["임의의 길이의 입력 데이터를 받아 고정된 길이의 해쉬 값으로 변환한다.","주로 공개키 암호화 방식에서 키 생성을 위해 사용한다.","대표적인 해쉬 알고리즘으로 HAVAL, SHA-1 등이 있다.","해쉬 함수는 일방향 함수(One-way function)이다."],"ans":2,"rate":52,"wiki":[{"title":"해시","url":"https://itwiki.kr/w/해시"}],"exp":{"concept":"해시(Hash) 함수는 길이가 제각각인 입력을 받아 항상 같은 길이의 해시 값으로 바꾼다. 해시 값으로 원래 입력을 되돌릴 수 없는 일방향 함수이며, 주로 데이터 무결성 검증, 전자 서명, 비밀번호 저장 등에 쓴다. 공개키 암호의 키를 만드는 용도로 쓰지 않는다.","choices":[{"verdict":"오답","why":"해시 함수는 임의 길이의 입력을 고정된 길이의 해시 값으로 변환한다."},{"verdict":"정답","why":"해시는 주로 무결성 검증과 전자 서명 등에 쓰이며, 공개키 암호화 방식의 키 생성을 위해 사용한다는 설명은 틀리다."},{"verdict":"오답","why":"HAVAL, SHA-1은 대표적인 해시 알고리즘이다(MD5, SHA-256 등도 있음)."},{"verdict":"오답","why":"해시 함수는 해시 값으로 원래 입력을 알아낼 수 없는 일방향 함수다."}],"keywords":[{"term":"해시 함수(Hash Function)","desc":"임의 길이 입력을 고정 길이 값으로 바꾸는 일방향 함수"},{"term":"대표 해시 알고리즘","desc":"MD5, SHA 계열(SHA-1, SHA-256), HAVAL"},{"term":"무결성 검증","desc":"해시 값을 비교해 데이터가 변조되지 않았는지 확인"}],"memo":"해시는 '지문 찍기'. 원본을 숨기거나 키를 만드는 게 아니라 같은지 비교하는 데 쓴다."}},{"id":"written-2021-2-94","no":94,"unit":"정보시스템 구축 관리","q":"IPSec(IP Security)에 대한 설명으로 틀린 것은?","choices":["암호화 수행시 일방향 암호화만 지원한다.","ESP는 발신지 인증, 데이터 무결성, 기밀성 모두를 보장한다.","운영 모드는 Tunnel 모드와 Transport 모드로 분류된다.","AH는 발신지 호스트를 인증하고, IP 패킷의 무결성을 보장한다."],"ans":1,"rate":71,"wiki":[{"title":"IPSec","url":"https://itwiki.kr/w/IPSec"}],"exp":{"concept":"IPSec은 네트워크 계층(IP)에서 패킷을 보호하는 보안 프로토콜이다. 인증과 무결성을 제공하는 AH(Authentication Header)와, 여기에 기밀성(암호화)까지 제공하는 ESP(Encapsulating Security Payload)를 쓴다. 운영 모드는 전송(Transport) 모드와 터널(Tunnel) 모드가 있고, 양방향 암호화를 지원한다.","choices":[{"verdict":"정답","why":"IPSec은 양방향 암호화를 지원하므로 일방향 암호화만 지원한다는 설명은 틀리다."},{"verdict":"오답","why":"ESP는 발신지 인증, 데이터 무결성, 기밀성을 모두 보장한다."},{"verdict":"오답","why":"IPSec의 운영 모드는 터널(Tunnel) 모드와 전송(Transport) 모드로 나뉜다."},{"verdict":"오답","why":"AH는 발신지 호스트를 인증하고 IP 패킷의 무결성을 보장한다(기밀성은 제공하지 않음)."}],"keywords":[{"term":"AH(Authentication Header)","desc":"발신지 인증과 무결성 제공, 암호화(기밀성) 없음"},{"term":"ESP(Encapsulating Security Payload)","desc":"발신지 인증, 무결성, 기밀성 모두 제공"},{"term":"전송 모드","desc":"IP 패킷의 데이터(페이로드)만 보호"},{"term":"터널 모드","desc":"IP 헤더를 포함한 패킷 전체를 보호, VPN에 사용"}],"memo":"AH는 '인증만', ESP는 '인증+암호화'. 암호화(Encryption) 기능은 E가 들어간 ESP에 있다."}},{"id":"written-2021-2-95","no":95,"unit":"정보시스템 구축 관리","q":"메모리상에서 프로그램의 복귀 주소와 변수 사이에 특정 값을 저장해 두었다가 그 값이 변경되었을 경우 오버플로우 상태로 가정하여 프로그램 실행을 중단하는 기술은?","choices":["Stack Guard","Bridge","ASLR","FIN"],"ans":1,"rate":84,"wiki":[{"title":"버퍼 오버플로우","url":"https://itwiki.kr/w/버퍼 오버플로우"}],"exp":{"concept":"스택 가드(Stack Guard)는 스택 버퍼 오버플로우 공격을 막는 기술이다. 함수의 복귀 주소와 변수 사이에 카나리(Canary)라는 특정 값을 넣어 두고, 함수가 끝날 때 그 값이 바뀌었으면 오버플로우가 일어난 것으로 보고 실행을 중단한다. 광산의 카나리아가 위험을 먼저 알려 주는 것과 같다.","choices":[{"verdict":"정답","why":"복귀 주소와 변수 사이에 카나리 값을 두고 변경 여부로 오버플로우를 감지해 실행을 중단하는 기술은 스택 가드다."},{"verdict":"오답","why":"브리지(Bridge)는 같은 네트워크의 두 세그먼트를 MAC 주소 기준으로 연결하는 데이터 링크 계층 장비다."},{"verdict":"오답","why":"ASLR(Address Space Layout Randomization)은 프로그램이 실행될 때마다 메모리 주소 배치를 무작위로 바꾸어 공격자가 주소를 예측하지 못하게 하는 기술이다."},{"verdict":"오답","why":"FIN은 TCP 연결을 종료할 때 쓰는 제어 플래그다."}],"keywords":[{"term":"스택 가드(Stack Guard)","desc":"복귀 주소 앞에 카나리 값을 두어 스택 오버플로우를 탐지"},{"term":"스택 쉴드(Stack Shield)","desc":"함수 시작 시 복귀 주소를 별도 영역에 저장했다가 종료 시 비교"},{"term":"ASLR","desc":"메모리 주소 배치를 무작위화해 공격을 어렵게 함"}],"memo":"'특정 값을 끼워 두고 변하면 중단'은 스택 가드(카나리), '복귀 주소를 따로 보관'은 스택 쉴드."}},{"id":"written-2021-2-96","no":96,"unit":"정보시스템 구축 관리","q":"침입차단 시스템(방화벽) 중 다음과 같은 형태의 구축 유형은?\n<img src=\"data/img/eip_written_20210515_096.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["Block Host","Tree Host","Screened Subnet","Ring Homed"],"ans":3,"rate":52,"wiki":[{"title":"방화벽","url":"https://itwiki.kr/w/방화벽"}],"exp":{"concept":"스크린드 서브넷(Screened Subnet)은 외부 라우터와 내부 라우터 사이에 완충 지대(DMZ)를 두고, 그곳에 베스천 호스트(Bastion Host)와 외부 공개용 서버를 놓는 방화벽 구축 유형이다. 그림에서 인터넷과 연결된 라우터 아래 구간에 Bastion Host와 서버들이 있고, 두 번째 라우터를 지나야 내부 PC에 닿는 구조가 이에 해당한다.","choices":[{"verdict":"오답","why":"Block Host는 방화벽 구축 유형의 표준 이름이 아니다."},{"verdict":"오답","why":"Tree Host는 방화벽 구축 유형의 표준 이름이 아니다."},{"verdict":"정답","why":"라우터 두 대 사이의 완충 구간에 베스천 호스트와 서버를 두어 내부망을 이중으로 보호하는 구조는 스크린드 서브넷이다."},{"verdict":"오답","why":"Ring Homed는 방화벽 구축 유형의 표준 이름이 아니다. 이름이 비슷한 듀얼 홈드(Dual-Homed) 게이트웨이는 네트워크 카드 2개를 가진 베스천 호스트로 내부·외부를 나누는 유형이다."}],"keywords":[{"term":"스크린드 서브넷(Screened Subnet)","desc":"외부·내부 라우터 사이에 DMZ를 두는 구조, 가장 안전하지만 비용·속도 부담"},{"term":"스크린드 호스트(Screened Host)","desc":"스크리닝 라우터와 베스천 호스트를 함께 사용하는 구조"},{"term":"듀얼 홈드 게이트웨이","desc":"네트워크 카드 2개를 가진 베스천 호스트로 내·외부를 분리"},{"term":"베스천 호스트(Bastion Host)","desc":"외부 접근을 받아 내부망을 보호하는 강화된 호스트"}],"memo":"라우터가 두 대이고 그 사이에 공간(서브넷)이 있으면 스크린드 서브넷."}},{"id":"written-2021-2-97","no":97,"unit":"정보시스템 구축 관리","q":"Secure OS의 보안 기능으로 거리가 먼 것은?","choices":["식별 및 인증","임의적 접근 통제","고가용성 지원","강제적 접근 통제"],"ans":3,"rate":74,"wiki":[{"title":"보안_OS","url":"https://itwiki.kr/w/보안_OS"}],"exp":{"concept":"보안 운영체제(Secure OS)는 운영체제의 커널에 보안 기능을 넣어 해킹으로부터 시스템을 보호하는 운영체제다. 보안 기능으로 식별 및 인증, 임의적 접근 통제(DAC), 강제적 접근 통제(MAC), 객체 재사용 보호, 완전한 중재, 감사 및 감사 기록 축소, 안전한 경로, 해킹 방지 등이 있다.","choices":[{"verdict":"오답","why":"식별 및 인증은 사용자가 누구인지 확인하는 Secure OS의 보안 기능이다."},{"verdict":"오답","why":"임의적 접근 통제(DAC)는 소유자가 접근 권한을 정하는 Secure OS의 보안 기능이다."},{"verdict":"정답","why":"고가용성 지원은 장애가 나도 서비스를 계속 제공하기 위한 기능(이중화 등)으로, Secure OS의 보안 기능이 아니다."},{"verdict":"오답","why":"강제적 접근 통제(MAC)는 보안 등급에 따라 시스템이 접근을 강제로 통제하는 Secure OS의 보안 기능이다."}],"keywords":[{"term":"Secure OS","desc":"커널에 보안 기능을 내장한 운영체제"},{"term":"임의적 접근 통제(DAC)","desc":"데이터 소유자가 접근 권한을 부여"},{"term":"강제적 접근 통제(MAC)","desc":"보안 등급(레이블)에 따라 시스템이 접근을 통제"},{"term":"고가용성(HA)","desc":"장애에도 서비스를 계속 제공하는 성질, 보안 기능이 아님"}],"memo":"Secure OS 기능은 '누가(인증)·무엇을(접근 통제)·기록(감사)'. 가용성은 보안 기능 목록에 없다."}},{"id":"written-2021-2-98","no":98,"unit":"정보시스템 구축 관리","q":"서버에 열린 포트 정보를 스캐닝해서 보안취약점을 찾는데 사용하는 도구는?","choices":["type","mkdir","ftp","nmap"],"ans":4,"rate":68,"wiki":[{"title":"Nmap","url":"https://itwiki.kr/w/Nmap"}],"exp":{"concept":"엔맵(nmap, Network Mapper)은 네트워크의 호스트와 열린 포트, 실행 중인 서비스를 스캔하는 도구다. 관리자는 보안 점검에, 공격자는 취약점 탐색에 사용한다.","choices":[{"verdict":"오답","why":"type은 Windows 명령 프롬프트에서 텍스트 파일 내용을 출력하는 명령이며, 포트 스캐닝 도구가 아니다."},{"verdict":"오답","why":"mkdir은 디렉터리(폴더)를 만드는 명령이다."},{"verdict":"오답","why":"ftp는 파일을 전송하는 프로토콜 또는 그 클라이언트 명령이다."},{"verdict":"정답","why":"nmap은 서버의 열린 포트 정보를 스캐닝해 보안 취약점을 찾는 데 쓰는 도구다."}],"keywords":[{"term":"nmap","desc":"네트워크 호스트·포트·서비스 스캐닝 도구"},{"term":"포트 스캐닝","desc":"대상 시스템의 열린 포트를 찾아 실행 중인 서비스를 알아내는 기법"},{"term":"mkdir","desc":"디렉터리를 생성하는 명령"}],"memo":"n(network) + map(지도). 네트워크 지도를 그리듯 열린 포트를 찾는다."}},{"id":"written-2021-2-99","no":99,"unit":"정보시스템 구축 관리","q":"서로 다른 네트워크 대역에 있는 호스트들 상호간에 통신할 수 있도록 해주는 네트워크 장비는?","choices":["L2 스위치","HIPO","라우터","RAD."],"ans":3,"rate":81,"wiki":[{"title":"L2 스위치","url":"https://itwiki.kr/w/L2 스위치"},{"title":"라우터","url":"https://itwiki.kr/w/라우터"},{"title":"HIPO","url":"https://itwiki.kr/w/HIPO"}],"exp":{"concept":"라우터는 네트워크 계층(3계층) 장비로, IP 주소를 보고 서로 다른 네트워크 사이에서 패킷이 갈 최적의 경로를 정해 전달한다. 같은 네트워크 안에서 MAC 주소로 프레임을 전달하는 장비는 L2 스위치다.","choices":[{"verdict":"오답","why":"L2 스위치는 데이터 링크 계층 장비로, MAC 주소를 기반으로 같은 네트워크 안에서 프레임을 전달한다."},{"verdict":"오답","why":"HIPO(Hierarchy Input Process Output)는 시스템의 기능을 계층적으로 표현하는 문서화 도구로, 네트워크 장비가 아니다."},{"verdict":"정답","why":"라우터는 서로 다른 네트워크 대역의 호스트끼리 통신하도록 경로를 정해 패킷을 전달하는 네트워크 장비다."},{"verdict":"오답","why":"RAD(Rapid Application Development)는 짧은 기간에 빠르게 개발하는 소프트웨어 개발 방법론으로, 네트워크 장비가 아니다."}],"keywords":[{"term":"라우터(Router)","desc":"3계층 장비, IP 주소로 서로 다른 네트워크 간 경로 설정·패킷 전달"},{"term":"L2 스위치","desc":"2계층 장비, MAC 주소로 같은 네트워크 내 프레임 전달"},{"term":"게이트웨이(Gateway)","desc":"프로토콜이 서로 다른 네트워크를 연결하는 장비"}],"memo":"'서로 다른 네트워크'를 잇는 것은 라우터, '같은 네트워크' 안은 스위치."}},{"id":"written-2021-2-100","no":100,"unit":"정보시스템 구축 관리","q":"암호화 키와 복호화 키가 동일한 암호화 알고리즘은?","choices":["RSA","AES","DSA","ECC"],"ans":2,"rate":58,"wiki":[{"title":"대칭키 암호화","url":"https://itwiki.kr/w/대칭키 암호화"},{"title":"RSA","url":"https://itwiki.kr/w/RSA"},{"title":"AES","url":"https://itwiki.kr/w/AES"},{"title":"DSA","url":"https://itwiki.kr/w/DSA"},{"title":"ECC","url":"https://itwiki.kr/w/ECC"}],"exp":{"concept":"암호화 알고리즘은 암호화 키와 복호화 키가 같은 대칭키(비밀키) 방식과, 서로 다른 공개키·개인키 쌍을 쓰는 비대칭키(공개키) 방식으로 나뉜다. AES는 미국 표준 기술 연구소(NIST)가 DES를 대체하려고 선정한 대칭키 블록 암호다.","choices":[{"verdict":"오답","why":"RSA는 큰 수의 소인수 분해가 어렵다는 점을 이용한 비대칭키(공개키) 암호 알고리즘이다."},{"verdict":"정답","why":"AES는 암호화 키와 복호화 키가 같은 대칭키 암호 알고리즘이다."},{"verdict":"오답","why":"DSA(Digital Signature Algorithm)는 공개키 방식의 전자 서명 알고리즘이다."},{"verdict":"오답","why":"ECC(Elliptic Curve Cryptography)는 타원 곡선을 이용한 비대칭키(공개키) 암호 알고리즘이다."}],"keywords":[{"term":"대칭키 암호","desc":"암호화·복호화 키가 같음, DES, AES, SEED, ARIA, IDEA"},{"term":"비대칭키 암호","desc":"공개키로 암호화하고 개인키로 복호화, RSA, ECC, ElGamal"},{"term":"AES","desc":"NIST가 DES를 대체해 채택한 대칭키 블록 암호, 128비트 블록"}],"memo":"공개키 방식은 RSA·ECC·DSA·ElGamal처럼 수학 문제(소인수 분해, 이산 로그, 타원 곡선)에 기대는 것들이다."}}]};